def rsrc_path(*parts: str) -> str:
    import os, sys
    base = getattr(sys, "_MEIPASS", os.path.dirname(__file__))
    return os.path.join(base, *parts)
ICON_PATH = os.environ.get("LARIX_ICON_PATH", rsrc_path("icon", "logo_transparent_multi.ico"))

def program_dir() -> str:
    """Return the directory where the program is running from.
    - If frozen (PyInstaller), use the executable's directory.
    - Else, use the directory of this file; fallback to CWD.
    """
    try:
        if getattr(sys, "frozen", False):
            d = os.path.dirname(sys.executable) or os.getcwd()
            return os.path.abspath(d)
    except Exception:
        pass
    try:
        return os.path.abspath(os.path.dirname(__file__))
    except Exception:
        return os.getcwd()

# --- Simple sync logger -------------------------------------------------------
_SYNC_LOGGER = None  # type: ignore[var-annotated]

def _sync_log_path() -> str:
    try:
        base = program_dir()
    except Exception:
        base = os.getcwd()
    # write into a predictable folder near the app
    path = os.path.join(base, "sync", "_sync_debug.log")
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
    except Exception:
        pass
    return path

def _sync_logger() -> logging.Logger:
    global _SYNC_LOGGER
    if _SYNC_LOGGER is not None:
        return _SYNC_LOGGER
    logger = logging.getLogger("sync")
    logger.setLevel(logging.DEBUG)
    # avoid duplicate handlers on reload
    if not logger.handlers:
        try:
            fh = logging.FileHandler(_sync_log_path(), mode="a", encoding="utf-8")
            fmt = logging.Formatter("%(asctime)s [%(levelname)s] %(message)s")
            fh.setFormatter(fmt)
            logger.addHandler(fh)
        except Exception:
            pass
    _SYNC_LOGGER = logger
    return logger

def sync_log(msg: str, *args):
    try:
        _sync_logger().debug(msg.format(*args))
    except Exception:
        pass

def sync_exc(msg: str):
    try:
        _sync_logger().exception(msg)
    except Exception:
        pass

def normalize_id(value) -> str:
    """Normalize document/folder identifiers to opaque strings."""
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    try:
        return str(int(value))
    except (TypeError, ValueError):
        return str(value).strip()

def normalize_project_id(value) -> str:
    """Normalize project identifiers to opaque strings."""
    return normalize_id(value)


def _set_window_theme_dark(window, dark: bool = False) -> None:
    """Set Windows title bar theme (light/dark) for a window on Windows."""
    if platform.system() != "Windows":
        return
    try:
        import ctypes
        from ctypes import c_int, byref, sizeof
        hwnd = window.winId().__int__()
        # DWMWA_USE_IMMERSIVE_DARK_MODE = 20
        value = c_int(1 if dark else 0)
        ctypes.windll.dwmapi.DwmSetWindowAttribute(
            hwnd, 20, byref(value), sizeof(value)
        )
        # Title bar colors (Windows 11+)
        caption_color = 0x202020 if dark else 0xFFFFFF
        text_color = 0xFFFFFF if dark else 0x000000
        for attr, color in ((35, caption_color), (36, text_color)):
            try:
                cval = c_int(color)
                ctypes.windll.dwmapi.DwmSetWindowAttribute(hwnd, attr, byref(cval), sizeof(cval))
            except Exception:
                pass
    except Exception:
        pass

def _cleanup_sync_log_file() -> None:
    """Flush sync debug log on app shutdown.

    ВАЖНО: лог не удаляем, чтобы история синхронизаций
    (включая список синхронизированных папок) сохранялась между запусками.
    """
    try:
        logger = _sync_logger()
        # Detach and close our handlers
        for h in list(logger.handlers):
            try:
                h.flush()
            except Exception:
                pass
            try:
                h.close()
            except Exception:
                pass
            try:
                logger.removeHandler(h)
            except Exception:
                pass
    except Exception:
        pass


# ============================================================================
# SYNC MODULE - Bidirectional sync with JSON state tracking
# ============================================================================

SYNC_STATE_FILE = "sync_state.json"


def _sync_state_path() -> str:
    """Получить путь к файлу состояния синхронизации в AppData."""
    try:
        app_data = os.getenv("APPDATA") or os.path.expanduser("~/.config")
        sync_dir = os.path.join(app_data, "LarixNexus")
        os.makedirs(sync_dir, exist_ok=True)
        return os.path.join(sync_dir, SYNC_STATE_FILE)
    except Exception:
        # Fallback to current directory
        return os.path.abspath(SYNC_STATE_FILE)


def load_sync_state() -> tuple[Dict[str, Dict[str, Any]], bool]:
    """
    Загрузить состояние синхронизации из файла.
    Возвращает кортеж: ({relative_path: {"createTime": timestamp}}, initial_sync_done)
    """
    path = _sync_state_path()
    if not os.path.exists(path):
        return {}, False
    
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data.get("files", {}), data.get("initial_sync_done", False)
    except Exception as e:
        sync_log("Ошибка загрузки sync_state.json: {}", str(e))
        return {}, False


def save_sync_state(files_state: Dict[str, Dict[str, Any]]) -> bool:
    """
    Сохранить состояние синхронизации в файл.
    files_state: {relative_path: {"createTime": timestamp, "lastModified": timestamp}}
    """
    path = _sync_state_path()
    state = {
        "version": 1,
        "last_sync": time.time(),
        "initial_sync_done": True,
        "files": files_state
    }
    
    try:
        # Атомарная запись через временный файл
        temp_path = path + ".tmp"
        with open(temp_path, 'w', encoding='utf-8') as f:
            json.dump(state, f, indent=2, ensure_ascii=False)
        
        # Замена файла
        if os.path.exists(path):
            os.remove(path)
        os.rename(temp_path, path)
        return True
    except Exception as e:
        sync_log("Ошибка сохранения sync_state.json: {}", str(e))
        return False


def get_local_files(local_root: str) -> Dict[str, Dict[str, Any]]:
    """
    Получить список локальных файлов И ПАПОК с их метаданными.
    Возвращает: {relative_path: {"createTime": timestamp, "lastModified": timestamp, "size": bytes, "is_folder": bool}}
    """
    files = {}
    
    if not os.path.exists(local_root):
        return files
    
    for root, dirs, filenames in os.walk(local_root):
        # Добавляем папки
        for dirname in dirs:
            full_path = os.path.join(root, dirname)
            rel_path = os.path.relpath(full_path, local_root).replace("\\", "/")
            
            try:
                stat = os.stat(full_path)
                files[rel_path] = {
                    "createTime": stat.st_ctime,
                    "lastModified": stat.st_mtime,
                    "size": 0,
                    "is_folder": True
                }
            except Exception as e:
                sync_log("Ошибка чтения метаданных папки {}: {}", full_path, str(e))
        
        # Добавляем файлы
        for filename in filenames:
            full_path = os.path.join(root, filename)
            rel_path = os.path.relpath(full_path, local_root).replace("\\", "/")
            
            try:
                stat = os.stat(full_path)
                files[rel_path] = {
                    "createTime": stat.st_ctime,
                    "lastModified": stat.st_mtime,
                    "size": stat.st_size
                }
            except Exception as e:
                sync_log("Ошибка чтения метаданных {}: {}", full_path, str(e))
    
    return files

 
def get_cloud_files(api, project_id: int | str, folder_id: int | str) -> Dict[str, Dict[str, Any]]:
    """
    Получить список облачных файлов с их метаданными.
    Возвращает: {relative_path: {"createTime": timestamp, "lastModified": timestamp, "size": bytes, "id": file_id}}
    """
    files = {}
    
    try:
        # ДИАГНОСТИКА: Сначала попробуем получить через list_folders (полное дерево проекта)
        sync_log("=" * 60)
        sync_log("ДИАГНОСТИКА: Получение облачных файлов")
        sync_log("project_id={}, folder_id={}", project_id, folder_id)
        sync_log("=" * 60)
        
        # Метод 1: Попробуем list_folders (возвращает полное дерево проекта)
        tree_root = None
        try:
            sync_log("Метод 1: Пробуем api.list_folders()...")
            folders_tree = api.list_folders(project_id, force=True)
            if folders_tree:
                sync_log("✓ list_folders вернул дерево с {} элементов верхнего уровня", len(folders_tree))
                
                # Найдём нужную папку в дереве
                def find_folder_in_tree(tree, target_id):
                    if not isinstance(tree, list):
                        return None
                    for item in tree:
                        if item.get("id") == target_id:
                            return item
                        # Рекурсивно ищем в children
                        children = item.get("children") or item.get("folders") or []
                        result = find_folder_in_tree(children, target_id)
                        if result:
                            return result
                    return None
                
                tree_root = find_folder_in_tree(folders_tree, folder_id)
                if tree_root:
                    sync_log("✓ Найдена папка {} в дереве проекта", folder_id)
                else:
                    sync_log("⚠ Папка {} не найдена в дереве, попробуем другой метод", folder_id)
            else:
                sync_log("⚠ list_folders вернул пустой результат")
        except Exception as e:
            sync_log("⚠ Ошибка list_folders: {}", str(e))
        
        # Метод 2: Если list_folders не сработал, используем get_folder_details
        if not tree_root:
            sync_log("Метод 2: Пробуем api.get_folder_details()...")
            folder_details = api.get_folder_details(folder_id, force=True)
            if not folder_details:
                sync_log("⚠ get_folder_details вернул пустой результат для folder_id={}", folder_id)
                return files
            
            sync_log("✓ Получены детали папки {}", folder_id)
            sync_log("Ключи в ответе: {}", str(list(folder_details.keys())))
            tree_root = folder_details
        
        # Обработка дерева
        def _process_tree(tree, parent_path="", level=0):
            if not isinstance(tree, list):
                sync_log("⚠ Дерево не является списком на уровне {}, путь: {}, type: {}", level, parent_path, type(tree).__name__)
                return
            
            sync_log("{}Обработка уровня {}, элементов: {}, путь: '{}'", "  " * level, level, len(tree), parent_path)
            
            for item in tree:
                if not isinstance(item, dict):
                    continue
                    
                item_type = item.get("type", "").lower()
                item_name = item.get("name") or item.get("title") or item.get("folderName") or item.get("originalName") or ""
                
                if item_type == "file":
                    if parent_path:
                        rel_path = f"{parent_path}/{item_name}"
                    else:
                        rel_path = item_name
                    
                    # ДИАГНОСТИКА: Показать ВСЕ поля элемента
                    sync_log("{}  RAW данные файла '{}':", "  " * level, item_name)
                    for key, value in item.items():
                        if key not in ("children", "folders", "items", "subFolders"):  # Не показываем вложенные структуры
                            sync_log("{}    {}: {}", "  " * level, key, repr(value))
                    
                    # Парсим даты с логированием
                    sync_log("{}  Парсинг временных меток для файла '{}':", "  " * level, rel_path)
                    
                    # ПРОБЛЕМА: list_folders НЕ ВОЗВРАЩАЕТ временные метки!
                    # API возвращает только: id, name, type, version, shared
                    # Решение: используем get_document_details для получения полной информации
                    
                    # Попробуем получить детали документа через API
                    file_id = normalize_id(item.get("id"))
                    if file_id:
                        try:
                            doc_details = api.get_document_details(file_id)
                            if doc_details:
                                sync_log("{}    Получены детали документа {}", "  " * level, file_id)
                                # ПРИОРИТЕТ: createTime (время создания в облаке), fallback: modifTime
                                raw_time = doc_details.get("createTime") or doc_details.get("createdAt") or doc_details.get("created") or doc_details.get("modifTime")
                                sync_log("{}    raw_time из document_details: {}", "  " * level, repr(raw_time))
                            else:
                                sync_log("{}    ⚠ get_document_details вернул None для id={}", "  " * level, file_id)
                                raw_time = None
                        except Exception as e:
                            sync_log("{}    ⚠ Ошибка get_document_details: {}", "  " * level, str(e))
                            raw_time = None
                    else:
                        raw_time = None
                    
                    # Парсим timestamp (API возвращает локальное время сервера)
                    modified_time = _parse_timestamp(raw_time, f"modifTime/createTime[{item_name}]")
                    create_time = modified_time  # Используем то же время для createTime
                    
                    files[rel_path] = {
                        "createTime": create_time,
                        "lastModified": modified_time,
                        "size": item.get("size", 0) or item.get("fileSize", 0),
                        "id": normalize_id(item.get("id")),
                        "folderId": normalize_id(item.get("folderId"))
                    }
                    sync_log("{}✓ Файл: {} (id={}, mtime={})", "  " * level, rel_path, item.get('id'), modified_time)
                
                elif item_type == "folder":
                    new_path = f"{parent_path}/{item_name}" if parent_path else item_name
                    
                    # ВАЖНО: Добавляем папку в результат для создания локально
                    # ПРИОРИТЕТ: createTime (время создания в облаке), fallback: modifTime
                    raw_time = item.get("createTime") or item.get("createdAt") or item.get("created") or item.get("modifTime")
                    
                    modified_time = _parse_timestamp(raw_time, f"modifTime/createTime[folder:{item_name}]")
                    create_time = modified_time
                    
                    files[new_path] = {
                        "createTime": create_time,
                        "lastModified": modified_time,
                        "size": 0,  # Папки не имеют размера
                        "id": normalize_id(item.get("id")),
                        "folderId": normalize_id(item.get("folderId")),
                        "is_folder": True  # Маркер, что это папка
                    }
                    
                    # Пробуем разные ключи для children
                    children = None
                    for key in ("children", "folders", "items", "subFolders"):
                        potential_children = item.get(key)
                        if isinstance(potential_children, list):
                            children = potential_children
                            break
                    
                    # Если детей нет в list_folders, запрашиваем через get_folder_details
                    if not children:
                        folder_id = normalize_id(item.get("id"))
                        if folder_id:
                            try:
                                sync_log("{}  Запрос содержимого папки {} через get_folder_details...", "  " * level, folder_id)
                                folder_details = api.get_folder_details(folder_id, force=True)
                                if folder_details:
                                    # Пробуем извлечь детей из детальной информации
                                    for key in ("children", "folders", "items", "subFolders", "documents"):
                                        potential_children = folder_details.get(key)
                                        if isinstance(potential_children, list):
                                            children = potential_children
                                            sync_log("{}  ✓ Найдено {} элементов в папке {}", "  " * level, len(children), folder_id)
                                            break
                            except Exception as e:
                                sync_log("{}  ⚠ Ошибка get_folder_details: {}", "  " * level, str(e))
                    
                    if not children:
                        children = []
                    
                    sync_log("{}📁 Папка: {} (дочерних: {}) - ДОБАВЛЕНА", "  " * level, new_path, len(children))
                    _process_tree(children, new_path, level + 1)
                else:
                    sync_log("{}⚠ Неизвестный тип: {} для элемента {}", "  " * level, item_type, item_name)
        
        # Извлекаем дерево из корня
        tree = None
        
        # Пробуем разные ключи для получения дерева
        for key in ("children", "folders", "items", "documents", "content", "subFolders"):
            potential_tree = tree_root.get(key)
            if isinstance(potential_tree, list):
                tree = potential_tree
                sync_log("✓ Дерево найдено в ключе '{}'", key)
                break
        
        if not tree:
            tree = []
            sync_log("⚠ Дерево не найдено ни в одном из ключей")
            sync_log("Доступные ключи: {}", str(list(tree_root.keys())))
        
        sync_log("Корневое дерево содержит {} элементов", len(tree))
        _process_tree(tree)
        
        sync_log("=" * 60)
        sync_log("✓ Всего найдено облачных файлов: {}", len(files))
        sync_log("=" * 60)
        
    except Exception as e:
        sync_log("=" * 60)
        sync_log("❌ ОШИБКА получения облачных файлов: {}", str(e))
        sync_log("=" * 60)
        sync_exc("get_cloud_files error")
    
    return files


def get_cloud_folder_structure(api, project_id: int | str, folder_id: int | str) -> Dict[str, str]:
    """
    Получить структуру папок в облаке.
    Возвращает: {relative_path: folder_id}
    """
    folders = {"": normalize_id(folder_id)}  # Корневая папка
    
    try:
        # Попробуем list_folders для получения полного дерева
        tree_root = None
        try:
            folders_tree = api.list_folders(project_id, force=True)
            if folders_tree:
                # Найдём нужную папку
                target_id_norm = normalize_id(folder_id)
                def find_folder_in_tree(tree, target_id_norm):
                    if not isinstance(tree, list):
                        return None
                    for item in tree:
                        if normalize_id(item.get("id")) == target_id_norm:
                            return item
                        children = item.get("children") or item.get("folders") or []
                        result = find_folder_in_tree(children, target_id_norm)
                        if result:
                            return result
                    return None
                
                tree_root = find_folder_in_tree(folders_tree, target_id_norm)
        except Exception:
            pass
        
        # Fallback к get_folder_details
        if not tree_root:
            folder_details = api.get_folder_details(folder_id, force=True)
            if not folder_details:
                return folders
            tree_root = folder_details
        
        def _process_tree(tree, parent_path=""):
            if not isinstance(tree, list):
                return
            
            for item in tree:
                if not isinstance(item, dict):
                    continue
                
                item_type = item.get("type", "").lower()
                if item_type == "folder":
                    folder_name = item.get("name") or item.get("title") or item.get("folderName") or ""
                    new_path = f"{parent_path}/{folder_name}" if parent_path else folder_name
                    folders[new_path] = normalize_id(item.get("id"))
                    
                    # Пробуем разные ключи для children
                    children = None
                    for key in ("children", "folders", "items", "subFolders"):
                        potential_children = item.get(key)
                        if isinstance(potential_children, list):
                            children = potential_children
                            break
                    
                    if children:
                        _process_tree(children, new_path)
        
        # Пробуем разные ключи для получения дерева
        tree = None
        for key in ("children", "folders", "items", "documents", "content", "subFolders"):
            potential_tree = tree_root.get(key)
            if isinstance(potential_tree, list):
                tree = potential_tree
                break
        
        if tree:
            _process_tree(tree)
        
    except Exception as e:
        sync_log("Ошибка получения структуры папок: {}", str(e))
    
    return folders


def _parse_timestamp(value: Any, field_name: str = "") -> float:
    """Парсинг timestamp из различных форматов.
    
    ВАЖНО: API возвращает время в UTC (например '09:35:37' означает 09:35 UTC).
    Локальная файловая система (os.getmtime) возвращает timestamp который при
    datetime.fromtimestamp() дает локальное время.
    Поэтому naive datetime строки интерпретируются как UTC и конвертируются в timestamp.
    
    Args:
        value: значение для парсинга
        field_name: имя поля для логирования
    
    Returns:
        Unix timestamp (секунды с 1970-01-01 00:00:00 UTC)
    """
    if not value:
        return 0.0
    
    # Если уже число
    if isinstance(value, (int, float)):
        # Если в миллисекундах
        if value > 1e12:
            result = value / 1000.0
        else:
            result = float(value)
        
        # ДИАГНОСТИКА
        from datetime import datetime
        dt_str = datetime.fromtimestamp(result).strftime("%Y-%m-%d %H:%M:%S")
        if field_name:
            sync_log("    _parse_timestamp({}): {} -> {} ({}) [numeric]", field_name, value, result, dt_str)
        
        return result
    
    # Если строка
    s = str(value).strip()
    
    # Попытка парсинга как число
    try:
        val = float(s)
        if val > 1e12:
            result = val / 1000.0
        else:
            result = val
        
        from datetime import datetime
        dt_str = datetime.fromtimestamp(result).strftime("%Y-%m-%d %H:%M:%S")
        if field_name:
            sync_log("    _parse_timestamp({}): '{}' -> {} ({}) [string->numeric]", field_name, s, result, dt_str)
        
        return result
    except:
        pass
    
    # ISO формат с указанием часового пояса
    try:
        from dateutil import parser
        from datetime import timezone, timedelta
        
        dt = parser.parse(s)
        
        # Если в строке нет явного часового пояса, интерпретируем как UTC
        if dt.tzinfo is None:
            # ВАЖНО: API возвращает время в UTC (например '09:35:37' = 09:35 UTC = 12:35 МСК)
            # Нужно преобразовать UTC в локальный timestamp для сравнения с os.getmtime()
            # os.getmtime() возвращает timestamp который при fromtimestamp() дает локальное время
            from datetime import timezone
            dt_utc = dt.replace(tzinfo=timezone.utc)
            result = dt_utc.timestamp()
            
            if field_name:
                sync_log("    _parse_timestamp({}): строка без TZ '{}' интерпретирована как UTC -> {} timestamp", 
                        field_name, s, result)
        else:
            result = dt.timestamp()
            if field_name:
                sync_log("    _parse_timestamp({}): '{}' -> {} [ISO with TZ]", field_name, s, result)
        
        from datetime import datetime as dt_class
        dt_str = dt_class.fromtimestamp(result).strftime("%Y-%m-%d %H:%M:%S")
        if field_name:
            sync_log("    -> {} ({})", field_name, result, dt_str)
        
        return result
    except Exception as e:
        if field_name:
            sync_log("    _parse_timestamp({}): ошибка парсинга ISO '{}': {}", field_name, s, str(e))
        pass
    
    # Известные форматы (интерпретируем как локальное системное время)
    formats = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%d.%m.%Y %H:%M:%S",
        "%d.%m.%Y %H:%M",
        "%d.%m.%Y"
    ]
    
    for fmt in formats:
        try:
            from datetime import datetime, timezone, timedelta
            dt = datetime.strptime(s, fmt)
            
            # Интерпретируем как UTC и конвертируем в локальный timestamp
            # API возвращает UTC время, нужно преобразовать для сравнения с os.getmtime()
            dt_utc = dt.replace(tzinfo=timezone.utc)
            result = dt_utc.timestamp()
            
            dt_str = datetime.fromtimestamp(result).strftime("%Y-%m-%d %H:%M:%S")
            if field_name:
                sync_log("    _parse_timestamp({}): '{}' (формат {}) интерпретировано как UTC -> {} ({})", 
                        field_name, s, fmt, result, dt_str)
            
            return result
        except:
            continue
    
    if field_name:
        sync_log("    _parse_timestamp({}): не удалось распарсить '{}'", field_name, s)
    
    return 0.0


def compare_and_plan_sync(
    old_state: Dict[str, Dict[str, Any]],
    local_files: Dict[str, Dict[str, Any]],
    cloud_files: Dict[str, Dict[str, Any]],
    tolerance: float = 2.0,
    is_initial_sync: bool = False
) -> list:
    """
    Сравнить старое состояние с текущим и составить план синхронизации.
    
    tolerance: допуск в секундах для сравнения timestamps (игнорируем различия меньше этого значения)
    is_initial_sync: Если True, все что в облаке но не локально - скачивается (игнорируется old_state)
    
    Возвращает список операций:
    [
        {"action": "download", "path": "...", "cloud_id": ...},
        {"action": "upload", "path": "..."},
        {"action": "delete_local", "path": "..."},
        {"action": "delete_cloud", "path": "...", "cloud_id": ...},
        {"action": "conflict_download", "path": "...", "cloud_id": ...},
        {"action": "conflict_upload", "path": "..."},
    ]
    """
    operations = []
    
    all_paths = set(old_state.keys()) | set(local_files.keys()) | set(cloud_files.keys())
    
    sync_log("")
    sync_log("ДИАГНОСТИКА СРАВНЕНИЯ:")
    sync_log("  Всего уникальных путей: {}", len(all_paths))
    sync_log("  В старом состоянии: {}", len(old_state))
    sync_log("  Локально сейчас: {}", len(local_files))
    sync_log("  В облаке сейчас: {}", len(cloud_files))
    sync_log("")
    
    for path in all_paths:
        was_in_old = path in old_state
        in_local = path in local_files
        in_cloud = path in cloud_files
        
        # ДИАГНОСТИКА: логируем состояние каждого файла/папки
        is_folder_local = local_files.get(path, {}).get("is_folder", False)
        is_folder_cloud = cloud_files.get(path, {}).get("is_folder", False)
        is_folder = is_folder_local or is_folder_cloud
        
        state_info = f"old={'✓' if was_in_old else '✗'} local={'✓' if in_local else '✗'} cloud={'✓' if in_cloud else '✗'}"
        type_info = "📁" if is_folder else "📄"
        
        # Новый файл только в облаке
        if in_cloud and not in_local and not was_in_old:
            sync_log("{} НОВЫЙ В ОБЛАКЕ: {} ({})", type_info, path, state_info)
            op = {
                "action": "download",
                "path": path,
                "cloud_id": cloud_files[path]["id"],
                "cloud_mtime": cloud_files[path].get("createTime")  # Используем createTime из облака
            }
            if cloud_files[path].get("is_folder"):
                op["is_folder"] = "true"
            operations.append(op)
        
        # Новый файл только локально
        elif in_local and not in_cloud and not was_in_old:
            sync_log("{} НОВЫЙ ЛОКАЛЬНО: {} ({})", type_info, path, state_info)
            operations.append({
                "action": "upload",
                "path": path
            })
        
        # Файл был, но удалён в облаке
        elif was_in_old and in_local and not in_cloud:
            sync_log("{} УДАЛЁН В ОБЛАКЕ (удаляем локально): {} ({})", type_info, path, state_info)
            op = {
                "action": "delete_local",
                "path": path
            }
            if local_files[path].get("is_folder"):
                op["is_folder"] = "true"
            else:
                op["is_folder"] = "false"
            operations.append(op)
        
        # Файл был, но удалён локально - КЛЮЧЕВОЙ МОМЕНТ!
        elif was_in_old and in_cloud and not in_local:
            # ВАЖНО: при начальной синхронизации НЕ удаляем из облака
            # (old_state может быть от предыдущего подключения, а локальная папка пустая)
            if is_initial_sync:
                sync_log("{} ПРИ НАЧАЛЬНОЙ СИНХРОНИЗАЦИИ: {} в облаке, будет скачан ({})", type_info, path, state_info)
                op = {
                    "action": "download",
                    "path": path,
                    "cloud_id": cloud_files[path]["id"],
                    "cloud_mtime": cloud_files[path].get("createTime")  # Используем createTime из облака
                }
                if cloud_files[path].get("is_folder"):
                    op["is_folder"] = "true"
                operations.append(op)
            else:
                sync_log("{} УДАЛЁН ЛОКАЛЬНО (удаляем в облаке): {} ({})", type_info, path, state_info)
                sync_log("    Детали: old_state={}, cloud_id={}", 
                        "да" if path in old_state else "нет",
                        cloud_files[path].get("id", "N/A"))
                op = {
                    "action": "delete_cloud",
                    "path": path,
                    "cloud_id": cloud_files[path]["id"]
                }
                if cloud_files[path].get("is_folder"):
                    sync_log("    Это папка - будет использован delete_folder")
                    op["is_folder"] = "true"
                operations.append(op)
        
        # Новый элемент только в облаке (не было в старом состоянии, не в локальных)
        # ПРОБЛЕМА: если папка была удалена локально, но НЕ была в old_state, 
        # то она попадет сюда и будет скачана заново!
        elif in_cloud and not in_local:
            # Это может быть НОВЫЙ файл ИЛИ файл, который был удален локально но не был в old_state
            if not was_in_old:
                sync_log("{} НОВЫЙ В ОБЛАКЕ или БЫЛ УДАЛЕН ЛОКАЛЬНО БЕЗ old_state: {} ({})", type_info, path, state_info)
                sync_log("    ВНИМАНИЕ: Если это была удаленная папка, она будет скачана заново!")
            else:
                sync_log("{} НЕОПРЕДЕЛЕННОЕ СОСТОЯНИЕ: {} ({})", type_info, path, state_info)
        
        # Файл есть в обоих местах - проверяем различия
        elif in_local and in_cloud:
            # Пропускаем папки - они не нуждаются в синхронизации содержимого
            if local_files[path].get("is_folder") or cloud_files[path].get("is_folder"):
                continue
            
            local_mtime = local_files[path].get("lastModified", 0)
            cloud_mtime = cloud_files[path].get("lastModified", 0)
            
            # ДИАГНОСТИКА: Логируем сравнение времени
            time_diff = abs(local_mtime - cloud_mtime)
            from datetime import datetime
            local_dt = datetime.fromtimestamp(local_mtime).strftime("%Y-%m-%d %H:%M:%S") if local_mtime else "N/A"
            cloud_dt = datetime.fromtimestamp(cloud_mtime).strftime("%Y-%m-%d %H:%M:%S") if cloud_mtime else "N/A"
            
            # Если различия больше tolerance
            if time_diff > tolerance:
                sync_log("⚠ Конфликт времени для '{}': локал={} ({}), облако={} ({}), разница={}с",
                        path, local_dt, local_mtime, cloud_dt, cloud_mtime, int(time_diff))
                
                # Выбираем более свежую версию
                if local_mtime > cloud_mtime:
                    sync_log("  → Решение: ЗАГРУЗИТЬ (локальный файл новее)")
                    operations.append({
                        "action": "conflict_upload",
                        "path": path,
                        "local_mtime": local_mtime,
                        "cloud_mtime": cloud_mtime
                    })
                else:
                    sync_log("  → Решение: СКАЧАТЬ (облачный файл новее)")
                    operations.append({
                        "action": "conflict_download",
                        "path": path,
                        "cloud_id": cloud_files[path]["id"],
                        "cloud_mtime": cloud_files[path].get("createTime"),  # Используем createTime для установки времени файла
                        "local_mtime": local_mtime
                    })
            else:
                # Файлы синхронизированы
                if time_diff > 0:
                    sync_log("✓ Синхронизирован '{}': разница={}с (в пределах допуска)", path, int(time_diff))
    
    return operations


def execute_sync_operations(
    api,
    project_id: int | str,
    folder_id: int | str,
    local_root: str,
    operations: list,
    dry_run: bool = False
) -> Dict[str, Any]:
    """
    Выполнить операции синхронизации.
    
    Возвращает статистику: {"downloaded": N, "uploaded": N, "deleted_local": N, "deleted_cloud": N, "errors": [...]}
    """
    stats = {
        "downloaded": 0,
        "uploaded": 0,
        "deleted_local": 0,
        "deleted_cloud": 0,
        "errors": []
    }
    
    # Получаем структуру папок в облаке
    cloud_folders = get_cloud_folder_structure(api, project_id, normalize_id(folder_id))
    
    def ensure_cloud_folder(path: str) -> Optional[str]:
        """Убедиться, что папка существует в облаке. Возвращает folder_id или None при ошибке."""
        if path in cloud_folders:
            return cloud_folders[path]
        
        # Создаём папку
        parts = path.split("/")
        current_path = ""
        current_folder_id = normalize_id(folder_id)
        
        for part in parts:
            if current_path:
                current_path = f"{current_path}/{part}"
            else:
                current_path = part
            
            if current_path in cloud_folders:
                current_folder_id = cloud_folders[current_path]
            else:
                # Создаём новую папку
                if dry_run:
                    sync_log("[DRY RUN] Создать папку: {}", current_path)
                    cloud_folders[current_path] = "-1"  # Заглушка для dry run
                    current_folder_id = "-1"
                else:
                    sync_log("Создаю папку: {}", current_path)
                    try:
                        result = api.create_folder(project_id, current_folder_id, part)
                        if result and "id" in result:
                            new_folder_id = normalize_id(result["id"])
                            cloud_folders[current_path] = new_folder_id
                            current_folder_id = new_folder_id
                        else:
                            return None
                    except Exception as e:
                        sync_log("Ошибка создания папки {}: {}", current_path, str(e))
                        return None
        
        return normalize_id(current_folder_id)
    
    # СНАЧАЛА обрабатываем создание папок (download операции с is_folder)
    for op in operations:
        if op.get("is_folder") and op["action"] in ("download", "conflict_download"):
            path = op["path"]
            if dry_run:
                sync_log("[DRY RUN] Создать локальную папку: {}", path)
            else:
                local_path = os.path.join(local_root, path.replace("/", os.sep))
                os.makedirs(local_path, exist_ok=True)
                sync_log("📁 Создана папка: {}", path)
    
    # ЗАТЕМ обрабатываем файлы и удаление папок
    for op in operations:
        action = op["action"]
        path = op["path"]
        
        # Пропускаем ТОЛЬКО создание папок (download) - оно уже обработано выше
        if op.get("is_folder") and action in ("download", "conflict_download"):
            continue
        
        try:
            if action == "download" or action == "conflict_download":
                if dry_run:
                    sync_log("[DRY RUN] Скачать: {}", path)
                else:
                    sync_log("Скачиваю: {}", path)
                    local_path = os.path.join(local_root, path.replace("/", os.sep))
                    dir_path = os.path.dirname(local_path)
                    if dir_path:
                        os.makedirs(dir_path, exist_ok=True)
                        sync_log("  ✓ Создана локальная папка: {}", dir_path)
                    
                    cloud_id = op["cloud_id"]
                    with open(local_path, 'wb') as f:
                        success = api.write_file_to(cloud_id, f)
                    
                    if success:
                        stats["downloaded"] += 1
                        sync_log("  ✓ Скачан: {}", path)
                        
                        # Log sync action for notification filtering
                        try:
                            from PySide6.QtWidgets import QApplication
                            app = QApplication.instance()
                            if app:
                                for widget in app.topLevelWidgets():
                                    if hasattr(widget, '_log_user_action'):
                                        widget._log_user_action("sync", file_name=os.path.basename(path), folder_id=folder_id)
                                        break
                        except Exception:
                            pass
                        
                        # Устанавливаем время создания файла из облака (createTime)
                        # Это гарантирует, что локальный файл будет иметь то же время, что и в облаке
                        cloud_mtime = op.get("cloud_mtime")
                        if cloud_mtime:
                            try:
                                from datetime import datetime
                                cloud_dt = datetime.fromtimestamp(cloud_mtime).strftime("%Y-%m-%d %H:%M:%S")
                                os.utime(local_path, (cloud_mtime, cloud_mtime))
                                sync_log("  ✓ Установлено время из облака (createTime): {} -> {}", path, cloud_dt)
                            except Exception as e:
                                sync_log("  ⚠ Не удалось установить время файла: {}", str(e))
                        else:
                            sync_log("  ℹ Время файла не установлено (createTime отсутствует в облаке), используется время загрузки")
                    else:
                        stats["errors"].append(f"Не удалось скачать {path}")
                        sync_log("  ✗ Ошибка скачивания: {}", path)
            
            elif action == "upload" or action == "conflict_upload":
                if dry_run:
                    sync_log("[DRY RUN] Загрузить: {}", path)
                else:
                    sync_log("Загружаю: {}", path)
                    local_path_full = os.path.join(local_root, path.replace("/", os.sep))
                    filename = os.path.basename(path)
                    
                    # Определяем папку назначения
                    dir_path = os.path.dirname(path).replace("\\", "/")
                    if dir_path:
                        target_folder_id = ensure_cloud_folder(dir_path)
                        if target_folder_id is None:
                            stats["errors"].append(f"Не удалось создать папку для {path}")
                            continue
                    else:
                        target_folder_id = folder_id
                    
                    result = api.upload_file(target_folder_id, local_path_full, filename)
                    
                    if result:
                        stats["uploaded"] += 1
                        sync_log("  ✓ Загружен: {}", path)
                        
                        # Log sync action for notification filtering
                        try:
                            # Try to get MainWindow instance to log action
                            from PySide6.QtWidgets import QApplication
                            app = QApplication.instance()
                            if app:
                                for widget in app.topLevelWidgets():
                                    if hasattr(widget, '_log_user_action'):
                                        widget._log_user_action("sync", file_name=filename, folder_id=target_folder_id)
                                        break
                        except Exception:
                            pass
                        
                        # ВАЖНО: После загрузки получаем время из облака и синхронизируем локальный файл
                        # Сервер устанавливает своё время при загрузке, нужно синхронизировать локальный файл
                        try:
                            # Инвалидируем кеш и получаем свежие данные папки
                            api.cache.pop(f"folder:{normalize_id(target_folder_id)}", None)
                            folder_details = api.get_folder_details(target_folder_id, force=True)
                            
                            if folder_details:
                                # Ищем загруженный файл в списке документов
                                documents = folder_details.get("documents") or []
                                uploaded_doc = None
                                for doc in documents:
                                    doc_name = doc.get("originalName") or doc.get("fileName") or doc.get("name") or ""
                                    if doc_name == filename:
                                        uploaded_doc = doc
                                        break
                                
                                if uploaded_doc:
                                    # Получаем время модификации из облака
                                    from datetime import datetime
                                    tz_offset_min = _cloud_tz_offset_minutes()
                                    
                                    raw_time = (uploaded_doc.get("modifTime") or 
                                               uploaded_doc.get("createTime") or 
                                               uploaded_doc.get("updatedAt") or 
                                               uploaded_doc.get("createdAt"))
                                    
                                    if raw_time:
                                        cloud_mtime = parse_date_like(str(raw_time), tz_offset_min)
                                        if cloud_mtime > 0:
                                            os.utime(local_path_full, (cloud_mtime, cloud_mtime))
                                            cloud_dt = datetime.fromtimestamp(cloud_mtime).strftime("%Y-%m-%d %H:%M:%S")
                                            sync_log("  ✓ Синхронизировано время с облаком: {} -> {}", path, cloud_dt)
                        except Exception as e:
                            sync_log("  ⚠ Не удалось синхронизировать время файла: {}", str(e))
                    else:
                        stats["errors"].append(f"Не удалось загрузить {path}")
                        sync_log("  ✗ Ошибка загрузки: {}", path)
            
            elif action == "delete_local":
                if dry_run:
                    sync_log("[DRY RUN] Удалить локально: {}", path)
                else:
                    sync_log("Удаляю локально: {}", path)
                    local_path = os.path.join(local_root, path.replace("/", os.sep))
                    
                    if os.path.exists(local_path):
                        if op.get("is_folder"):
                            # Удаление папки (рекурсивно)
                            import shutil
                            shutil.rmtree(local_path)
                            sync_log("  ✓ Папка удалена локально: {}", path)
                        else:
                            # Удаление файла
                            os.remove(local_path)
                            sync_log("  ✓ Файл удалён локально: {}", path)
                        stats["deleted_local"] += 1
            
            elif action == "delete_cloud":
                if dry_run:
                    sync_log("[DRY RUN] Удалить в облаке: {}", path)
                else:
                    sync_log("Удаляю в облаке: {}", path)
                    cloud_id = op["cloud_id"]
                    
                    if op.get("is_folder"):
                        # Удаление папки в облаке
                        success = api.delete_folder(cloud_id)
                        if success:
                            sync_log("  ✓ Папка удалена в облаке: {}", path)
                        else:
                            sync_log("  ✗ Ошибка удаления папки в облаке: {}", path)
                    else:
                        # Удаление файла в облаке
                        success = api.delete_document(cloud_id)
                        if success:
                            sync_log("  ✓ Файл удалён в облаке: {}", path)
                        else:
                            sync_log("  ✗ Ошибка удаления файла в облаке: {}", path)
                    
                    if success:
                        stats["deleted_cloud"] += 1
                    else:
                        stats["errors"].append(f"Не удалось удалить в облаке {path}")
        
        except Exception as e:
            error_msg = f"Ошибка при {action} для {path}: {e}"
            sync_log(error_msg)
            stats["errors"].append(error_msg)
            sync_exc(f"execute_sync_operations error for {action}")
    
    return stats


def sync_files_new(
    api,
    project_id: int | str,
    folder_id: int | str,
    local_root: str,
    dry_run: bool = False,
    is_initial_sync: bool = False
) -> Dict[str, Any]:
    """
    Основная функция синхронизации.
    
    1. Загружает старое состояние из sync_state.json
    2. Получает текущее состояние локальных и облачных файлов
    3. Сравнивает и планирует операции
    4. Выполняет операции
    5. Сохраняет новое состояние
    
    Args:
        is_initial_sync: Если True, игнорируется old_state и все из облака скачивается
    
    Возвращает статистику выполнения.
    """
    # ВАЖНО: это первая строка лога - если вы её не видите, функция не запустилась!
    sync_log("!!! SYNC_FILES_NEW ВЫЗВАНА !!! project_id={} folder_id={} local_root='{}' dry_run={} is_initial_sync={}", 
             project_id, folder_id, local_root, dry_run, is_initial_sync)
    
    sync_log("=" * 60)
    sync_log("Начало синхронизации")
    if is_initial_sync:
        sync_log("РЕЖИМ: Начальная синхронизация (old_state будет проигнорирован)")
    sync_log("=" * 60)
    
    # 1. Загрузить старое состояние
    sync_log("[1/5] Загрузка предыдущего состояния...")
    old_state, initial_sync_done = load_sync_state()
    
    # При начальной синхронизации игнорируем старое состояние
    if is_initial_sync:
        sync_log("  НАЧАЛЬНАЯ СИНХРОНИЗАЦИЯ: old_state очищен (было {} элементов)", len(old_state))
        old_state = {}
    elif initial_sync_done:
        sync_log("  ПРОДОЛЖЕНИЕ СИНХРОНИЗАЦИИ: загружено {} элементов из предыдущего состояния", len(old_state))
        # Логируем папки из предыдущего состояния
        loaded_folders = sum(1 for f in old_state.values() if f.get("is_folder"))
        if loaded_folders > 0:
            sync_log("  Загруженные папки из предыдущего состояния:")
            for path, info in sorted(old_state.items()):
                if info.get("is_folder"):
                    from datetime import datetime
                    mtime_str = datetime.fromtimestamp(info.get("lastModified", 0)).strftime("%Y-%m-%d %H:%M:%S")
                    sync_log("    📁 {} (mtime: {})", path, mtime_str)
    else:
        sync_log("  Файлов в предыдущем состоянии: {}", len(old_state))
        
        # ДИАГНОСТИКА: Показать первые несколько элементов old_state
        if old_state:
            sync_log("  Примеры из old_state:")
            for i, (path, info) in enumerate(list(old_state.items())[:5]):
                from datetime import datetime
                mtime_str = datetime.fromtimestamp(info.get("lastModified", 0)).strftime("%Y-%m-%d %H:%M:%S")
                sync_log("    [{}] '{}': mtime={}", i+1, path, mtime_str)
    
    # 2. Получить текущее состояние
    sync_log("[2/5] Сканирование текущего состояния...")
    local_files = get_local_files(local_root)
    sync_log("  Локальных файлов: {}", len(local_files))
    
    # ДИАГНОСТИКА: Посчитать папки и файлы
    local_folders = sum(1 for f in local_files.values() if f.get("is_folder"))
    local_regular = len(local_files) - local_folders
    sync_log("    Из них папок: {}, файлов: {}", local_folders, local_regular)
    
    cloud_files = get_cloud_files(api, project_id, folder_id)
    sync_log("  Облачных файлов: {}", len(cloud_files))
    
    # ДИАГНОСТИКА: Посчитать папки и файлы в облаке
    cloud_folders = sum(1 for f in cloud_files.values() if f.get("is_folder"))
    cloud_regular = len(cloud_files) - cloud_folders
    sync_log("    Из них папок: {}, файлов: {}", cloud_folders, cloud_regular)
    
    # 3. Сравнить и спланировать
    sync_log("[3/5] Планирование операций синхронизации...")
    operations = compare_and_plan_sync(old_state, local_files, cloud_files, is_initial_sync=is_initial_sync)
    sync_log("  Запланировано операций: {}", len(operations))
    
    # Группировка по типам
    by_action = {}
    for op in operations:
        action = op["action"]
        by_action[action] = by_action.get(action, 0) + 1
    
    for action, count in sorted(by_action.items()):
        sync_log("    {}: {}", action, count)
    
    # 4. Выполнить операции
    sync_log("[4/5] Выполнение операций...")
    stats = execute_sync_operations(api, project_id, folder_id, local_root, operations, dry_run)
    
    # 5. Сохранить новое состояние
    if not dry_run:
        sync_log("[5/5] Сохранение нового состояния...")
        # Объединяем локальные и облачные файлы в новое состояние
        new_state = {}
        
        # Добавляем локальные (включая папки!)
        for path, info in local_files.items():
            new_state[path] = {
                "createTime": info["createTime"],
                "lastModified": info["lastModified"],
                "is_folder": info.get("is_folder", False)  # Сохраняем флаг папки
            }
        
        # Обновляем облачными (они приоритетнее для createTime)
        for path, info in cloud_files.items():
            if path in new_state:
                # Файл есть и локально и в облаке - берём облачное createTime
                new_state[path]["createTime"] = info["createTime"]
                # lastModified - самое свежее
                if info["lastModified"] > new_state[path]["lastModified"]:
                    new_state[path]["lastModified"] = info["lastModified"]
                # Обновляем флаг папки
                if info.get("is_folder"):
                    new_state[path]["is_folder"] = True
            else:
                # Только в облаке (но не было скачано в этой сессии)
                new_state[path] = {
                    "createTime": info["createTime"],
                    "lastModified": info["lastModified"],
                    "is_folder": info.get("is_folder", False)
                }
        
        # ДИАГНОСТИКА: Посчитать что сохраняем
        saved_folders = sum(1 for f in new_state.values() if f.get("is_folder"))
        saved_regular = len(new_state) - saved_folders
        sync_log("  Сохранено элементов: {} (папок: {}, файлов: {})", 
                len(new_state), saved_folders, saved_regular)
        
        # Логируем синхронизированные папки
        if saved_folders > 0:
            sync_log("  Синхронизированные папки:")
            for path, info in sorted(new_state.items()):
                if info.get("is_folder"):
                    from datetime import datetime
                    mtime_str = datetime.fromtimestamp(info.get("lastModified", 0)).strftime("%Y-%m-%d %H:%M:%S")
                    sync_log("    📁 {} (mtime: {})", path, mtime_str)
        
        save_sync_state(new_state)
        sync_log("  Сохранено файлов: {}", len(new_state))
    else:
        sync_log("[5/5] Пропуск сохранения (dry run режим)")
    
    # Итоговая статистика
    sync_log("=" * 60)
    sync_log("Синхронизация завершена")
    sync_log("=" * 60)
    sync_log("Скачано: {}", stats['downloaded'])
    sync_log("Загружено: {}", stats['uploaded'])
    sync_log("Удалено локально: {}", stats['deleted_local'])
    sync_log("Удалено в облаке: {}", stats['deleted_cloud'])
    
    if stats["errors"]:
        sync_log("Ошибок: {}", len(stats['errors']))
        for err in stats["errors"]:
            sync_log("  - {}", err)
    
    # Возвращаем результат в ожидаемом формате
    success = len(stats["errors"]) == 0
    return {
        "success": success,
        "stats": stats,
        "errors": stats["errors"]
    }

# ============================================================================
# SECURE CREDENTIAL STORAGE (keyring)
# ============================================================================
KEYRING_SERVICE = "LarixNexus"

def save_credential(username: str, credential_type: str, value: str) -> bool:
    """Save credential to system keyring.
    
    Args:
        username: User identifier
        credential_type: Type of credential (e.g., 'password', 'refresh_token', 'access_token')
        value: Credential value
    
    Returns:
        True if successful
    """
    try:
        key = f"{username}:{credential_type}"
        keyring.set_password(KEYRING_SERVICE, key, value)
        print(f"[KEYRING DEBUG] save_credential: saved {credential_type} for {username}")
        return True
    except Exception as e:
        print(f"[KEYRING DEBUG] save_credential ERROR: {e}")
        return False

def get_credential(username: str, credential_type: str) -> Optional[str]:
    """Get credential from system keyring.
    
    Args:
        username: User identifier
        credential_type: Type of credential
    
    Returns:
        Credential value or None
    """
    try:
        key = f"{username}:{credential_type}"
        result = keyring.get_password(KEYRING_SERVICE, key)
        if result:
            print(f"[KEYRING DEBUG] get_credential: found {credential_type} for {username}")
        else:
            print(f"[KEYRING DEBUG] get_credential: NOT found {credential_type} for {username}")
        return result
    except Exception as e:
        print(f"[KEYRING DEBUG] get_credential ERROR: {e}")
        return None

def delete_credential(username: str, credential_type: str) -> bool:
    """Delete credential from system keyring.
    
    Args:
        username: User identifier
        credential_type: Type of credential
    
    Returns:
        True if successful
    """
    try:
        key = f"{username}:{credential_type}"
        keyring.delete_password(KEYRING_SERVICE, key)
        return True
    except Exception:
        return False

def clear_all_credentials(username: str) -> None:
    """Clear all credentials for a user."""
    for cred_type in ['password', 'refresh_token', 'access_token']:
        try:
            delete_credential(username, cred_type)
        except Exception:
            pass

def debug_credentials_status(username: str) -> None:
    """Debug function to check what credentials are stored."""
    print(f"\n{'='*60}")
    print(f"[CREDENTIALS DEBUG] Status for user: {username}")
    print(f"{'='*60}")
    
    for cred_type in ['password', 'refresh_token', 'access_token']:
        cred = get_credential(username, cred_type)
        if cred:
            print(f"  ✓ {cred_type:15s}: FOUND ({cred[:10]}...)")
        else:
            print(f"  ✗ {cred_type:15s}: NOT FOUND")
    
    settings = load_settings()
    print(f"\n[SETTINGS DEBUG] settings.json:")
    print(f"  last_username:  {settings.get('last_username', 'NOT SET')}")
    print(f"  remember_me:    {settings.get('remember_me', False)}")
    print(f"  auto_login:     {settings.get('auto_login', False)}")
    print(f"{'='*60}\n")

