# SUBSCRIPTIONS STORAGE (global, shared)
# ============================================================================

def _subscriptions_path() -> str:
    """Get path to subscriptions JSON file."""
    app_data = os.getenv("APPDATA") or os.path.expanduser("~/.config")
    settings_dir = os.path.join(app_data, "LarixNexus", "settings")
    return os.path.join(settings_dir, "subscriptions.json")

def load_subscriptions() -> Dict:
    """Load global subscriptions. Returns empty structure if not found."""
    path = _subscriptions_path()
    default = {"version": 1, "roots": {}}
    return atomic_read_json(path, default=default)

def save_subscriptions(subs: Dict) -> bool:
    """Save global subscriptions."""
    path = _subscriptions_path()
    return atomic_write_json(path, subs, ensure_dir=True)

def update_subscription(project_id: int | str, folder_id: int | str, rel_path: str, 
                        subscribed: bool, last_seen_rev: int = 0) -> bool:
    """Atomically update subscription for a specific folder path."""
    path = _subscriptions_path()
    
    def updater(data: Dict) -> Dict:
        if "roots" not in data:
            data["roots"] = {}
        root_key = f"{project_id}-{folder_id}"
        if root_key not in data["roots"]:
            data["roots"][root_key] = {}
        
        if subscribed:
            data["roots"][root_key][rel_path] = {
                "subscribed": True,
                "last_seen_rev": int(last_seen_rev)
            }
        else:
            # Remove subscription
            data["roots"][root_key].pop(rel_path, None)
        
        return data
    
    return atomic_update_json(path, updater, default={"version": 1, "roots": {}})

# --- Sync decision helper ----------------------------------------------------
# NOTE: Legacy sync functions (scan_local, scan_cloud, apply_sync_plan, execute_sync) 
# have been removed. Use sync_module.sync_files() instead.

# ============================================================================
# DIFF ENGINE & CONFLICT RESOLUTION
# ============================================================================

def compute_file_hash(path: str) -> str:
    """Compute SHA256 hash of a file for conflict resolution."""
    try:
        h = hashlib.sha256()
        with open(path, 'rb') as f:
            while chunk := f.read(8192):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return ""

def resolve_conflict(local_entry: Dict, cloud_entry: Dict, local_path: str = "") -> str:
    """Resolve conflict using etag > mtime > size priority (last-writer-wins).
    
    Returns: "upload", "download", or "skip"
    """
    # Priority 1: etag/hash comparison
    cloud_etag = cloud_entry.get("etag", "")
    local_hash = local_entry.get("hash")
    
    if not local_hash and local_path and os.path.exists(local_path):
        local_hash = compute_file_hash(local_path)
        local_entry["hash"] = local_hash
    
    if cloud_etag and local_hash:
        if cloud_etag == local_hash:
            return "skip"  # Identical content
    
    # Priority 2: mtime comparison (with tolerance)
    local_mtime = int(local_entry.get("mtime", 0) or 0)
    cloud_mtime = int(cloud_entry.get("mtime", 0) or 0)
    
    if abs(local_mtime - cloud_mtime) > 2:  # 2 second tolerance
        if local_mtime > cloud_mtime:
            return "upload"
        else:
            return "download"
    
    # Priority 3: size comparison
    local_size = int(local_entry.get("size", 0) or 0)
    cloud_size = int(cloud_entry.get("size", 0) or 0)
    
    if local_size != cloud_size:
        # Tie-breaker: larger file wins (heuristic)
        if local_size > cloud_size:
            return "upload"
        else:
            return "download"
    
    return "skip"

def diff_snapshots(prev_snapshot: Dict[str, Dict], 
                   curr_local: Dict[str, Dict], 
                   curr_cloud: Dict[str, Dict],
                   local_root: str = "") -> list[Dict[str, Any]]:
    """Compute sync operations based on previous and current snapshots.
    
    Args:
        prev_snapshot: Previous snapshot {rel_path: {local: {...}, cloud: {...}}}
        curr_local: Current local scan results
        curr_cloud: Current cloud scan results
        local_root: Local root path for hash computation
    
    Returns:
        List of operations: [{"action": "upload|download|delete_local|delete_cloud|conflict|noop", "rel_path": "...", ...}]
    """
    operations = []
    all_paths = set(prev_snapshot.keys()) | set(curr_local.keys()) | set(curr_cloud.keys())
    
    for rel_path in sorted(all_paths):
        prev = prev_snapshot.get(rel_path, {})
        prev_local = prev.get("local", {})
        prev_cloud = prev.get("cloud", {})
        
        curr_l = curr_local.get(rel_path, {"exists": False})
        curr_c = curr_cloud.get(rel_path, {"exists": False})
        
        local_exists = curr_l.get("exists", False)
        cloud_exists = curr_c.get("exists", False)
        
        prev_local_existed = prev_local.get("exists", False)
        prev_cloud_existed = prev_cloud.get("exists", False)
        
        # Case 1: Both exist now
        if local_exists and cloud_exists:
            # Check if either changed
            local_changed = (curr_l.get("mtime") != prev_local.get("mtime") or 
                           curr_l.get("size") != prev_local.get("size"))
            cloud_changed = (curr_c.get("etag") != prev_cloud.get("etag") or
                           curr_c.get("mtime") != prev_cloud.get("mtime"))
            
            if local_changed and cloud_changed:
                # Conflict: both modified
                local_path = os.path.join(local_root, rel_path.replace("/", os.sep)) if local_root else ""
                action = resolve_conflict(curr_l, curr_c, local_path)
                operations.append({
                    "action": action,
                    "rel_path": rel_path,
                    "reason": "conflict_both_modified"
                })
            elif local_changed:
                operations.append({
                    "action": "upload",
                    "rel_path": rel_path,
                    "reason": "local_newer"
                })
            elif cloud_changed:
                operations.append({
                    "action": "download",
                    "rel_path": rel_path,
                    "reason": "cloud_newer"
                })
            else:
                operations.append({
                    "action": "noop",
                    "rel_path": rel_path,
                    "reason": "unchanged"
                })
        
        # Case 2: Only local exists
        elif local_exists and not cloud_exists:
            # Check if cloud existed before (not just in prev snapshot, but if we ever knew about it)
            # If prev_cloud existed OR if prev snapshot shows cloud side, cloud was deleted
            if prev_cloud_existed:
                # Cloud deleted -> delete local (or flag for tombstone)
                operations.append({
                    "action": "delete_local",
                    "rel_path": rel_path,
                    "reason": "cloud_deleted"
                })
            else:
                # New local file -> upload
                operations.append({
                    "action": "upload",
                    "rel_path": rel_path,
                    "reason": "new_local"
                })
        
        # Case 3: Only cloud exists
        elif cloud_exists and not local_exists:
            # CRITICAL FIX: Check if file existed locally in EITHER prev snapshot OR in previous scan
            # This handles the case where file was synced but then deleted locally
            if prev_local_existed or (prev.get("local") and prev["local"] != {"exists": False}):
                # Local deleted -> delete cloud (or flag for tombstone)
                operations.append({
                    "action": "delete_cloud",
                    "rel_path": rel_path,
                    "reason": "local_deleted"
                })
            else:
                # New cloud file -> download
                operations.append({
                    "action": "download",
                    "rel_path": rel_path,
                    "reason": "new_cloud"
                })
        
        # Case 4: Neither exists (both deleted)
        else:
            if prev_local_existed or prev_cloud_existed:
                operations.append({
                    "action": "noop",
                    "rel_path": rel_path,
                    "reason": "both_deleted"
                })
    
    return operations

