def _white_variant_path(path: str) -> str:
    """Return original path without writing a file.
    Previously this function generated a white-tinted copy on disk; to avoid any
    filesystem writes, we now return the input path unchanged and rely on in-memory
    tinting via load_white_icon/_themed_icon where possible.
    """
    return path


def _get_white_icon_path_for_dark_theme(path: str) -> str:
    """Generate a white-tinted icon and return its path for use in dark theme CSS."""
    if not path or not os.path.exists(path):
        return path or ""
    
    try:
        # Create a white tinted version and save to temp
        pm = QPixmap(path)
        if not pm.isNull() and _should_tint_icon_white(path):
            white_pm = _tint_pixmap(pm, QColor(Qt.white))
            # Save to temp file
            temp_name = f"white_{os.path.basename(path)}"
            temp_path = os.path.join(tempfile.gettempdir(), temp_name)
            white_pm.save(temp_path)
            return temp_path.replace("\\", "/")
    except Exception:
        pass
    
    return path.replace("\\", "/")


def _should_tint_icon_white(path: str) -> bool:
    """Determine if an icon should be tinted white for dark theme.
    Returns False for Settings and Refresh icons to keep them unchanged."""
    if not path:
        return False
    
    # Keep Settings and Refresh icons unchanged as requested
    path_lower = path.lower()
    if "setting" in path_lower or "gear" in path_lower:
        return False
    if "refresh" in path_lower:
        return False
    
    return True


def load_white_icon(path: str) -> QIcon:
    if not path:
        return QIcon()
    cached = _WHITE_ICON_CACHE.get(path)
    if cached is not None:
        return cached
    try:
        if not os.path.exists(path):
            icon = QIcon()
        else:
            pm = QPixmap(path)
            if pm.isNull():
                icon = QIcon(path)
            else:
                # Only tint white if should be tinted (exclude Settings/Refresh)
                if _should_tint_icon_white(path):
                    tinted_pm = _tint_pixmap(pm, QColor(Qt.white))  # Use pure white for better visibility
                    icon = _icon_from_pixmap_variants(tinted_pm)
                else:
                    icon = _icon_from_pixmap_variants(pm)  # Keep original colors
    except Exception:
        icon = QIcon(path)
    _WHITE_ICON_CACHE[path] = icon
    return icon


def white_tinted_icon(source: QIcon) -> QIcon:
    if source.isNull():
        return source
    icon = QIcon()
    try:
        for size in (16, 20, 24, 28, 32, 40, 48, 64):
            pm = source.pixmap(size, size)
            if pm.isNull():
                continue
            # Use light gray instead of pure white for better visibility
            icon.addPixmap(_tint_pixmap(pm, QColor("#e0e0e0")))
    except Exception:
        return source
    return icon if not icon.isNull() else source


def themed_icon(path: str) -> QIcon:
    """Load an icon with appropriate theming based on current theme.
    In dark mode, most icons are tinted light gray except Settings and Refresh."""
    if not path:
        return QIcon()
    
    # Check if we're in dark mode
    try:
        app = QApplication.instance()
        if app and _is_dark_mode():
            return load_white_icon(path)
        else:
            return QIcon(path)
    except Exception:
        return QIcon(path)

def _sanitize_filename(name: str) -> str:
    """Return filename safe for Windows/macOS/Linux (no path separators, no reserved chars)."""
    if not isinstance(name, str):
        name = str(name or "")
    # Strip directories
    name = name.replace("\\", "/").split("/")[-1]
    # Remove reserved characters on Windows
    forbidden = set('<>:"/\\|?*')
    cleaned = ''.join('_' if ch in forbidden or ord(ch) < 32 else ch for ch in name)
    cleaned = cleaned.strip().rstrip('. ')
    if not cleaned:
        cleaned = "file"
    # Limit very long names
    if len(cleaned) > 240:
        base, ext = os.path.splitext(cleaned)
        cleaned = (base[:230] + ext) if len(ext) < 10 else cleaned[:240]
    return cleaned


def human_readable_size(size_bytes: int | float) -> str:
    """Convert bytes to human readable format (KB, MB, GB, etc.)."""
    try:
        size = float(size_bytes or 0)
        for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
            if size < 1024.0:
                return f"{size:.1f} {unit}"
            size /= 1024.0
        return f"{size:.1f} PB"
    except Exception:
        return str(size_bytes)


class SortHeader(QHeaderView):
    def __init__(self, orientation, parent=None, icon_up_path=None, icon_down_path=None):
        super().__init__(orientation, parent)
        self._icon_px = 12
        self._dark_mode = False
        self._up_path = icon_up_path or ""
        self._down_path = icon_down_path or ""
        self._pm_up = self._load_icon(self._up_path)
        self._pm_dn = self._load_icon(self._down_path)
        self.setSectionsClickable(True)
        self.setSortIndicatorShown(True)
        # Включаем отслеживание мыши для hover эффектов
        self.setMouseTracking(True)
        self.viewport().setMouseTracking(True)

    def _load_icon(self, path: str) -> QPixmap:
        if not path:
            return QPixmap()

        pm = QPixmap()
        if self._dark_mode:
            try:
                icon = load_white_icon(path)
                pm = icon.pixmap(QSize(self._icon_px, self._icon_px))
            except Exception:
                pm = QPixmap()

        if pm.isNull():
            pm = QPixmap(path or "")
            if self._dark_mode and not pm.isNull():
                # Fallback tinting when icon pixmap generation failed
                pm = _tint_pixmap(pm, QColor(Qt.white))

        if pm.isNull():
            return pm

        return pm.scaled(self._icon_px, self._icon_px, Qt.KeepAspectRatio, Qt.SmoothTransformation)

    def set_dark_mode(self, enabled: bool) -> None:
        if self._dark_mode == enabled:
            return
        self._dark_mode = enabled
        self._pm_up = self._load_icon(self._up_path)
        self._pm_dn = self._load_icon(self._down_path)
        # print(f"DEBUG: SortHeader.set_dark_mode called with enabled={enabled}, now _dark_mode={self._dark_mode}")
        self.viewport().update()
        self.update()

    def _ensure_icons_loaded(self):
        if self._pm_up.isNull() and self._up_path:
            self._pm_up = self._load_icon(self._up_path)
        if self._pm_dn.isNull() and self._down_path:
            self._pm_dn = self._load_icon(self._down_path)

    def paintSection(self, painter, rect, logicalIndex):
        # Проверяем состояние сортировки
        was_sort_shown = self.isSortIndicatorShown()
        is_sort_col = (logicalIndex == self.sortIndicatorSection())
        
        # ВСЕГДА отключаем стандартный индикатор Qt перед рисованием
        if was_sort_shown and is_sort_col:
            self.setSortIndicatorShown(False)
        
        # Рисуем секцию БЕЗ стандартного индикатора
        super().paintSection(painter, rect, logicalIndex)
        
        # Восстанавливаем флаг (но НЕ рисуем стрелку в светлой теме)
        if was_sort_shown and is_sort_col:
            self.setSortIndicatorShown(True)
        
        # Если это не колонка сортировки - выходим
        if not was_sort_shown or not is_sort_col:
            return
        
        # Далее рисуем стрелку - в светлой теме белую, в тёмной - видимую
        self._ensure_icons_loaded()
        
        # Проверяем hover/pressed состояние секции
        is_hovered = False
        is_pressed = False
        try:
            cursor_pos = self.mapFromGlobal(QCursor.pos())
            if rect.contains(cursor_pos):
                is_hovered = True
                if QApplication.mouseButtons() & Qt.LeftButton:
                    is_pressed = True
        except Exception:
            pass
        
        # Выбираем стрелку (вверх/вниз)
        pm = self._pm_up if self.sortIndicatorOrder() == Qt.AscendingOrder else self._pm_dn
        
        # Красим стрелку в зависимости от темы
        if not pm.isNull():
            if self._dark_mode:
                # Тёмная тема - белая стрелка
                pm = _tint_pixmap(pm, QColor("#FFFFFF"))
            else:
                # Светлая тема - чёрная стрелка
                pm = _tint_pixmap(pm, QColor("#000000"))

        if pm.isNull():
            # В светлой теме БЕЗ hover не рисуем векторную стрелку
            if not self._dark_mode and not (is_hovered or is_pressed):
                return
            
            # Рисуем векторную стрелку
            painter.save()
            sz = self._icon_px
            text = str(self.model().headerData(logicalIndex, Qt.Horizontal, Qt.DisplayRole) or "")
            x = min(rect.x() + 8 + painter.fontMetrics().horizontalAdvance(text) + 6,
                    rect.right() - sz - 4)
            y = rect.y() + (rect.height() - sz) // 2
            path = QPainterPath()
            if self.sortIndicatorOrder() == Qt.AscendingOrder:
                path.moveTo(x, y + sz); path.lineTo(x + sz, y + sz); path.lineTo(x + sz, y); path.closeSubpath()
            else:
                path.moveTo(x, y); path.lineTo(x + sz, y); path.lineTo(x + sz, y + sz); path.closeSubpath()
            painter.setPen(Qt.NoPen)
            
            # Выбираем цвет в зависимости от темы и состояния
            if is_hovered or is_pressed:
                if self._dark_mode:
                    painter.setBrush(QColor("#000000"))  # Черный на оранжевом фоне
                else:
                    painter.setBrush(QColor("#888888"))  # Серый для видимости
            else:
                # Тёмная тема - светло-серый (в светлой мы уже вышли выше)
                painter.setBrush(QColor("#f0f0f0"))
            
            painter.drawPath(path)
            painter.restore()
            return

        text = str(self.model().headerData(logicalIndex, Qt.Horizontal, Qt.DisplayRole) or "")
        text_w = painter.fontMetrics().horizontalAdvance(text)
        x = min(rect.x() + 8 + text_w + 6, rect.right() - pm.width() - 4)
        y = rect.y() + (rect.height() - pm.height()) // 2
        
        # Рисуем только если pixmap не пустой (в светлой теме при hover pm может быть пустым)
        if not pm.isNull():
            painter.save()
            painter.drawPixmap(x, y, pm)
            painter.restore()

    def sectionSizeFromContents(self, logicalIndex):
        sz = super().sectionSizeFromContents(logicalIndex)
        h = max(sz.height(), self._icon_px + 6)
        extra_w = self._icon_px + 8
        return QSize(sz.width() + extra_w, h)
    
    def mouseMoveEvent(self, event):
        """Перерисовываем при движении мыши для обновления hover состояния стрелок"""
        super().mouseMoveEvent(event)
        self.viewport().update()
    
    def leaveEvent(self, event):
        """Перерисовываем когда мышь покидает header"""
        super().leaveEvent(event)
        self.viewport().update()

class ThemeToggle(QAbstractButton):
    def __init__(self, sun_icon_path: str = "", moon_icon_path: str = "", parent=None):
        super().__init__(parent)
        self.setObjectName("themeToggle")
        self.setCheckable(True)
        self.setCursor(Qt.PointingHandCursor)
        self.setFocusPolicy(Qt.NoFocus)
        self.setMinimumSize(58, 26)
        self.setMaximumHeight(28)
        self._sun_icon = self._load_icon(sun_icon_path)
        self._moon_icon = self._load_icon(moon_icon_path)
        self._shift = 0.0
        self._anim = QPropertyAnimation(self, b"shift", self)
        self._anim.setDuration(180)
        self._anim.setEasingCurve(QEasingCurve.OutCubic)
        self.toggled.connect(self._animate_toggle)

    @staticmethod
    def _load_icon(path: str) -> QPixmap:
        if path and os.path.exists(path):
            pm = QPixmap(path)
            if not pm.isNull():
                return pm
        return QPixmap()

    def snap_to_state(self) -> None:
        self._set_shift(1.0 if self.isChecked() else 0.0)

    def _animate_toggle(self, checked: bool) -> None:
        self._anim.stop()
        self._anim.setStartValue(self._shift)
        self._anim.setEndValue(1.0 if checked else 0.0)
        self._anim.start()

    def sizeHint(self) -> QSize:
        return QSize(66, 28)

    def minimumSizeHint(self) -> QSize:
        return QSize(58, 26)

    def _get_shift(self) -> float:
        return self._shift

    def _set_shift(self, value: float) -> None:
        value = max(0.0, min(1.0, float(value)))
        if not math.isclose(self._shift, value, rel_tol=1e-3):
            self._shift = value
            self.update()

    shift = Property(float, _get_shift, _set_shift)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        rect = self.rect()
        track_rect = QRectF(rect.adjusted(1, 1, -1, -1))

        # Background track - светлее, менее серый
        dark = self.isChecked()  # checked => dark theme
        track_color = QColor("#555555") if dark else QColor("#e8e8e8")
        painter.setPen(Qt.NoPen)
        painter.setBrush(track_color)
        radius = track_rect.height() / 2.0
        painter.drawRoundedRect(track_rect, radius, radius)

        # Knob (draw before icons to avoid covering them)
        knob_margin = 3
        knob_d = track_rect.height() - knob_margin * 2
        knob_x = track_rect.left() + knob_margin + (track_rect.width() - 2 * knob_margin - knob_d) * self._shift
        knob_rect = QRectF(knob_x, track_rect.top() + knob_margin, knob_d, knob_d)
        knob_color = QColor("#101010") if dark else QColor("#fdfdfd")
        painter.setBrush(knob_color)
        painter.drawEllipse(knob_rect)

        # Decorative icons
        icon_size = int(track_rect.height() * 0.5)
        center_y = track_rect.center().y()
        left_x = track_rect.left() + 6
        right_x = track_rect.right() - icon_size - 6
        sun_on_left = self._shift >= 0.5
        sun_x = left_x if sun_on_left else right_x
        moon_x = right_x if sun_on_left else left_x
        if icon_size > 0:
            # prepare pixmaps; black in light theme, white in dark theme
            sun_pm = QPixmap()
            moon_pm = QPixmap()
            tint = QColor(Qt.white) if dark else QColor("#222222")
            if not self._sun_icon.isNull():
                _sun = self._sun_icon.scaled(icon_size, icon_size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                sun_pm = _tint_pixmap(_sun, tint)
            if not self._moon_icon.isNull():
                _moon = self._moon_icon.scaled(icon_size, icon_size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                moon_pm = _tint_pixmap(_moon, tint)

            # highlight the selected theme icon: sun for light, moon for dark (яркий оранжевый)
            painter.save()
            painter.setPen(Qt.NoPen)
            if not dark and not sun_pm.isNull():
                # light theme selected -> highlight sun
                highlight_size = icon_size + 8
                painter.setBrush(QColor("#F7921E"))
                painter.drawEllipse(QRectF(
                    sun_x - (highlight_size - icon_size) / 2,
                    center_y - highlight_size / 2,
                    highlight_size,
                    highlight_size
                ))
            elif dark and not moon_pm.isNull():
                # dark theme selected -> highlight moon
                highlight_size = icon_size + 8
                painter.setBrush(QColor("#F7921E"))
                painter.drawEllipse(QRectF(
                    moon_x - (highlight_size - icon_size) / 2,
                    center_y - highlight_size / 2,
                    highlight_size,
                    highlight_size
                ))
            painter.restore()

            # draw icons on top
            if not sun_pm.isNull():
                painter.drawPixmap(int(sun_x), int(center_y - sun_pm.height() / 2), sun_pm)
            if not moon_pm.isNull():
                painter.drawPixmap(int(moon_x), int(center_y - moon_pm.height() / 2), moon_pm)

    

