def get_files_flat(tree, parent_path=""):
    """Get flat list of all files AND folders in a tree structure (recursive)"""
    if not isinstance(tree, list):
        return []
    items = []
    for item in tree:
        if not isinstance(item, dict):
            continue
        
        item_type = item.get("type")
        name = item.get("originalName") or item.get("name") or "Без имени"
        
        if item_type == "file":
            # Add file to list
            items.append({
                "id": item["id"],
                "name": name,
                "type": "file",
                "updatedAt": item.get("updatedAt"),
                "path": parent_path
            })
        elif item_type == "folder":
            # Add folder to list
            folder_name = get_title(item)
            new_path = f"{parent_path}/{folder_name}" if parent_path else folder_name
            
            items.append({
                "id": item["id"],
                "name": folder_name,
                "type": "folder",
                "updatedAt": item.get("updatedAt"),
                "path": parent_path
            })
            
            # Recursively process children
            children = item.get("children")
            if children is None:
                children = []
            if isinstance(children, list):
                items.extend(get_files_flat(children, new_path))
    return items


def compare_file_states(old_files, new_files, filter_func=None):
    """Compare two file states and return list of changes
    
    Intelligently detects:
    - New files
    - Modified files (version updates - same name, different ID/timestamp)
    - Deleted files
    - Renamed files (same ID, different name)
    
    Args:
        old_files: Previous state
        new_files: Current state
        filter_func: Optional callable(change_type, file_id, file_name) -> bool
                    Returns True if change should be EXCLUDED (filtered out)
    """
    def _norm_id(value):
        try:
            if value is None:
                return ""
            return normalize_id(value)
        except Exception:
            return str(value).strip()

    def _norm_name_key(f):
        try:
            name = str(f.get("name", "")).strip()
            path = str(f.get("path", "")).replace("\\", "/").strip("/")
            ftype = f.get("type", "file")
            return (name, path, ftype)
        except Exception:
            return ("", "", f.get("type", "file"))

    old_dict_by_id = {_norm_id(f.get("id")): f for f in old_files}
    new_dict_by_id = {_norm_id(f.get("id")): f for f in new_files}
    
    print(f"[COMPARE] old_dict_by_id has {len(old_dict_by_id)} entries, new_dict_by_id has {len(new_dict_by_id)} entries")
    
    # Also index by name+path for detecting version updates
    old_dict_by_name = {}
    for f in old_files:
        key = _norm_name_key(f)
        old_dict_by_name[key] = f
    
    new_dict_by_name = {}
    for f in new_files:
        key = _norm_name_key(f)
        new_dict_by_name[key] = f
    
    print(f"[COMPARE] old_dict_by_name has {len(old_dict_by_name)} entries, new_dict_by_name has {len(new_dict_by_name)} entries")
    
    changes = []
    processed_old_ids = set()
    processed_new_ids = set()
    
    # First pass: detect modifications by ID and renames
    for fid, new_file in new_dict_by_id.items():
        if fid in old_dict_by_id:
            old_file = old_dict_by_id[fid]
            processed_old_ids.add(fid)
            processed_new_ids.add(fid)
            
            # Check for rename (same ID, different name)
            if new_file.get("name") != old_file.get("name"):
                change = {"type": "renamed", "file": new_file, "old_name": old_file.get("name")}
                if not (filter_func and filter_func("renamed", fid, new_file.get("name", ""))):
                    changes.append(change)
                continue
            
            # Check for modification (same ID and name, different timestamp)
            if new_file.get("updatedAt") != old_file.get("updatedAt"):
                change = {"type": "modified", "file": new_file}
                if filter_func and filter_func("modified", fid, new_file.get("name", "")):
                    print(f"[FILTER] Skipping user-initiated MODIFIED: {new_file.get('name')}")
                    continue
                changes.append(change)
    
    # Second pass: detect new files and version updates
    for fid, new_file in new_dict_by_id.items():
        if fid in processed_new_ids:
            continue
        
        name_key = _norm_name_key(new_file)
        
        # Check if file with same name existed (version update)
        if name_key in old_dict_by_name:
            old_file = old_dict_by_name[name_key]
            processed_old_ids.add(old_file["id"])
            processed_new_ids.add(fid)
            
            # This is a version update (same name/path, different ID)
            change = {"type": "modified", "file": new_file, "version_update": True}
            if filter_func and filter_func("modified", fid, new_file.get("name", "")):
                print(f"[FILTER] Skipping user-initiated MODIFIED (version update): {new_file.get('name')}")
                continue
            changes.append(change)
        else:
            # Truly new file
            change = {"type": "new", "file": new_file}
            if filter_func and filter_func("new", fid, new_file.get("name", "")):
                print(f"[FILTER] Skipping user-initiated NEW: {new_file.get('name')}")
                continue
            changes.append(change)
            processed_new_ids.add(fid)
    
    # Third pass: detect deleted files
    print(f"[COMPARE] Checking for deleted files, processed_old_ids has {len(processed_old_ids)} entries")
    for fid, old_file in old_dict_by_id.items():
        if fid in processed_old_ids:
            continue
        
        name_key = _norm_name_key(old_file)
        
        # Check if file with same name still exists with different ID (version update - already handled)
        if name_key in new_dict_by_name:
            # This old ID was replaced by a new version - don't show as deleted
            processed_old_ids.add(fid)
            print(f"[COMPARE] File {old_file.get('name')} (id={fid}) has same name in new state with different ID - version update, not deleted")
            continue
        
        # Truly deleted
        print(f"[COMPARE] DELETED file: {old_file.get('name')} (id={fid}), path={old_file.get('path')}")
        change = {"type": "deleted", "file": old_file}
        if filter_func and filter_func("deleted", fid, old_file.get("name", "")):
            print(f"[FILTER] Skipping user-initiated DELETED: {old_file.get('name')}")
            continue
        changes.append(change)
    
    print(f"[COMPARE] Total changes detected: {len(changes)}")
    for change in changes:
        print(f"[COMPARE]   - {change.get('type')}: {change.get('file', {}).get('name')}")
    
    return changes


# --- API клиент ---
class APIClient:
    def __init__(self, base_url: str):
        self.base_url = base_url.rstrip("/")
        self.token = None
        self.refresh_token = None
        self.current_username = None
        self.cache = {}
        
        # Try to restore previous session from keyring
        try:
            self._load_auth()
        except Exception:
            pass

    # --- secure auth persistence (keyring) ---
    def _save_auth(self) -> None:
        """Save auth tokens to keyring. Always saves credentials for auto-login."""
        try:
            if not self.current_username:
                print("[AUTH DEBUG] _save_auth: no username, skipping")
                return
            
            print(f"[AUTH DEBUG] _save_auth: saving credentials for user '{self.current_username}'")
            
            # Save access token (always, for current session)
            if self.token:
                save_credential(self.current_username, "access_token", self.token)
                print(f"[AUTH DEBUG] - saved access_token: {self.token[:20]}...")
            
            # Save refresh token (always, for auto-login on restart)
            if self.refresh_token:
                save_credential(self.current_username, "refresh_token", self.refresh_token)
                print(f"[AUTH DEBUG] - saved refresh_token: {self.refresh_token[:20]}...")
            
            # Update settings - always remember last username and enable auto-login
            settings = load_settings()
            settings["last_username"] = self.current_username
            settings["remember_me"] = True  # Always true - credentials always saved
            settings["auto_login"] = True   # Enable auto-login
            save_settings(settings)
            print(f"[AUTH DEBUG] - saved settings: auto_login=True, remember_me=True, last_username={self.current_username}")
            
            # Show diagnostic status
            debug_credentials_status(self.current_username)
        except Exception as e:
            print(f"[AUTH DEBUG] _save_auth ERROR: {e}")
            pass

    def _load_auth(self) -> bool:
        """Load auth tokens from keyring. Returns True if tokens were loaded and validated.
        
        Tries in order:
        1. Refresh token → refresh to get new access token
        2. Password → login to get new tokens
        3. Access token → direct use (may be expired)
        """
        try:
            print("[AUTH DEBUG] _load_auth: starting auto-login attempt")
            settings = load_settings()
            username = settings.get("last_username", "")
            
            if not username:
                print("[AUTH DEBUG] _load_auth: no last_username found, skipping auto-login")
                return False
            
            print(f"[AUTH DEBUG] _load_auth: found last_username='{username}'")
            
            # Show diagnostic status at start
            debug_credentials_status(username)
            
            # Step 1: Try refresh token
            refresh_token = get_credential(username, "refresh_token")
            if refresh_token:
                print(f"[AUTH DEBUG] _load_auth: found refresh_token: {refresh_token[:20]}...")
                self.current_username = username
                self.refresh_token = refresh_token
                
                # Try to refresh access token
                if self._refresh_access_token():
                    print("[AUTH DEBUG] _load_auth: SUCCESS via refresh_token")
                    return True
                else:
                    print("[AUTH DEBUG] _load_auth: refresh_token failed, trying next method")
            else:
                print("[AUTH DEBUG] _load_auth: no refresh_token found")
            
            # Step 2: Try password login (fallback)
            password = get_credential(username, "password")
            if password:
                print(f"[AUTH DEBUG] _load_auth: found password: {password[:3]}***")
                # Try to login with saved password
                if self.login(username, password):
                    print("[AUTH DEBUG] _load_auth: SUCCESS via password login")
                    return True
                else:
                    print("[AUTH DEBUG] _load_auth: password login failed, trying next method")
            else:
                print("[AUTH DEBUG] _load_auth: no password found in keyring")
            
            # Step 3: Fall back to access token if available
            access_token = get_credential(username, "access_token")
            if access_token:
                print(f"[AUTH DEBUG] _load_auth: found access_token: {access_token[:20]}...")
                self.current_username = username
                self.token = access_token
                print("[AUTH DEBUG] _load_auth: SUCCESS via access_token (may be expired)")
                return True
            else:
                print("[AUTH DEBUG] _load_auth: no access_token found")
            
            print("[AUTH DEBUG] _load_auth: FAILED - no valid credentials found")
            return False
        except Exception as e:
            print(f"[AUTH DEBUG] _load_auth ERROR: {e}")
            return False

    def _clear_auth(self) -> None:
        """Clear all auth tokens from keyring."""
        try:
            if self.current_username:
                clear_all_credentials(self.current_username)
            
            settings = load_settings()
            settings["remember_me"] = False
            settings["last_username"] = ""
            save_settings(settings)
        except Exception:
            pass

    def _refresh_access_token(self) -> bool:
        """Refresh access token using refresh token. Returns True if successful."""
        if not self.refresh_token:
            print("[AUTH DEBUG] _refresh_access_token: no refresh_token available")
            return False
        
        print(f"[AUTH DEBUG] _refresh_access_token: attempting refresh with token: {self.refresh_token[:20]}...")
        url = f"{self.base_url}/api/auth/refresh"
        try:
            r = requests.post(
                url,
                json={"refresh_token": self.refresh_token},
                headers={"accept": "*/*", "Content-Type": "application/json"},
                timeout=12
            )
            
            print(f"[AUTH DEBUG] _refresh_access_token: got status {r.status_code}")
            
            if r.status_code != 200:
                # Refresh token is invalid
                print(f"[AUTH DEBUG] _refresh_access_token: FAILED - status {r.status_code}, response: {r.text[:200]}")
                # DON'T clear auth here - let fallback methods try
                return False
            
            data = r.json()
            print(f"[AUTH DEBUG] _refresh_access_token: response data keys: {list(data.keys())}")
            
            access_token = data.get("token") or data.get("accessToken") or data.get("access_token")
            refresh_token = data.get("refreshToken") or data.get("refresh_token")
            
            if access_token:
                self.token = access_token
                print(f"[AUTH DEBUG] _refresh_access_token: got new access_token: {access_token[:20]}...")
                
                if refresh_token:
                    self.refresh_token = refresh_token
                    print(f"[AUTH DEBUG] _refresh_access_token: got new refresh_token: {refresh_token[:20]}...")
                
                # Save updated tokens (always save)
                self._save_auth()
                print("[AUTH DEBUG] _refresh_access_token: SUCCESS")
                return True
            
            print("[AUTH DEBUG] _refresh_access_token: FAILED - no access_token in response")
            return False
        except requests.RequestException as e:
            print(f"[AUTH DEBUG] _refresh_access_token: RequestException - {e}")
            return False

    def _headers(self):
        h = {"accept": "*/*"}
        if self.token:
            h["Authorization"] = f"Bearer {self.token}"
        return h

    def _handle_401(self) -> bool:
        """Handle 401 error by trying to refresh token.
        
        Returns:
            True if token was refreshed successfully
        """
        if self.refresh_token:
            if self._refresh_access_token():
                return True
        
        # Token refresh failed, logout
        self.logout()
        return False

    def is_available(self, timeout: int = 6) -> bool:
        """Lightweight availability check.
        Tries a tiny authenticated call; treats any non-network failure as available
        (e.g., 401 means server reachable but not authorized).
        """
        try:
            if not self.base_url:
                return False
            url = f"{self.base_url}/api/project/list"
            r = requests.get(url, headers=self._headers(), timeout=max(2, int(timeout)))
            # 2xx/3xx reachable; 401 also indicates server reachable
            return r.status_code < 500
        except requests.RequestException:
            return False

    def login(self, username: str, password: str) -> bool:
        """Login with username and password.
        
        Args:
            username: Username
            password: Password
        
        Returns:
            True if login successful
            
        Note:
            Credentials are always saved for auto-login on restart.
            To logout, use logout() or click "Сменить пользователя".
        """
        print(f"[AUTH DEBUG] login: attempting login for user '{username}'")
        url = f"{self.base_url}/api/admin/login"
        payload = {"username": username, "password": password, "app_code": ""}
        try:
            r = requests.post(url, json=payload, headers={"accept": "*/*","Content-Type":"application/json"}, timeout=12)
            if r.status_code == 401:
                print(f"[AUTH DEBUG] login: 401 Unauthorized for user '{username}'")
                return False
            r.raise_for_status()
            data = r.json()
            
            # Extract tokens
            token = data.get("token") or data.get("accessToken") or data.get("access_token")
            refresh_token = data.get("refreshToken") or data.get("refresh_token")
            
            if not token:
                print(f"[AUTH DEBUG] login: no token in response for user '{username}'")
                return False
            
            self.token = token
            self.refresh_token = refresh_token
            self.current_username = username
            
            print(f"[AUTH DEBUG] login: SUCCESS for user '{username}'")
            print(f"[AUTH DEBUG] - token: {token[:20]}...")
            print(f"[AUTH DEBUG] - refresh_token: {refresh_token[:20] if refresh_token else 'None'}...")
            
            # Always save password to keyring for fallback auto-login
            save_credential(username, "password", password)
            print(f"[AUTH DEBUG] - saved password to keyring")
            
            # Persist session (always save)
            self._save_auth()
            return True
        except requests.RequestException as e:
            print(f"[AUTH DEBUG] login: RequestException - {e}")
            return False

    def logout(self):
        """Logout and clear all stored credentials."""
        self.token = None
        self.refresh_token = None
        username = self.current_username
        self.current_username = None
        self.cache.clear()
        
        # Clear persisted session
        self._clear_auth()

    def list_projects(self):
        """List all projects. Auto-retries once on 401."""
        if not self.token: 
            return []
        
        url = f"{self.base_url}/api/project/list"
        for attempt in range(2):
            try:
                r = requests.get(url, headers=self._headers(), timeout=12)
                if r.status_code == 401:
                    if attempt == 0 and self._handle_401():
                        continue  # Retry with new token
                    return []
                r.raise_for_status()
                data = r.json()
                return data if isinstance(data, list) else []
            except requests.RequestException:
                return []
        return []

    def _cached_get(self, key: str):
        it = self.cache.get(key)
        if not it: return None
        ts, data = it
        if (time.time() - ts) < CACHE_TTL_SEC: return data
        return None

    def _stringify_id(self, raw_id) -> str:
        """Normalize document/folder identifiers that may now be opaque strings."""
        if raw_id is None:
            return ""
        if isinstance(raw_id, str):
            return raw_id.strip()
        try:
            return str(int(raw_id))
        except (TypeError, ValueError):
            return str(raw_id).strip()

    def list_folders(self, project_id: int | str, force: bool = False):
        """List folders in a project. Auto-retries once on 401."""
        key = f"tree:{project_id}"
        if not force:
            cached = self._cached_get(key)
            if cached is not None: 
                return cached
        
        if not self.token: 
            return []
        
        url = f"{self.base_url}/api/folder/list/{project_id}"
        for attempt in range(2):
            try:
                r = requests.get(url, headers=self._headers(), timeout=20)
                if r.status_code == 401:
                    if attempt == 0 and self._handle_401():
                        continue  # Retry with new token
                    return []
                r.raise_for_status()
                data = r.json()
                if isinstance(data, list):
                    self.cache[key] = (time.time(), data)
                    return data
                return []
            except requests.RequestException:
                return []
        return []

    def get_document_details(self, document_id: int | str):
        doc_id = self._stringify_id(document_id)
        if not doc_id:
            return None
        cache_key = f"doc:{doc_id}"
        cached = self._cached_get(cache_key)
        if cached is not None: return cached
        url = f"{self.base_url}/api/document/{doc_id}"
        try:
            r = requests.get(url, headers=self._headers(), timeout=12)
            if r.status_code == 401: self.logout(); return None
            r.raise_for_status()
            data = r.json()
            self.cache[cache_key] = (time.time(), data)
            return data
        except requests.RequestException:
            return None

    def generate_document_link(self, document_id: int | str, mode: str = "view"):
        doc_id = self._stringify_id(document_id)
        if not doc_id:
            return {"ok": False, "error": "bad-id"}
        mode = (mode or "view").lower()
        suffix = "download" if mode == "download" else "view"
        url = f"{self.base_url}/api/document/generate-link/{doc_id}/{suffix}"
        try:
            r = requests.get(url, headers=self._headers(), timeout=12)
            if r.status_code == 401:
                self.logout()
                return {"ok": False, "error": "unauthorized"}
            r.raise_for_status()
            try:
                data = r.json()
            except ValueError:
                return {"ok": False, "error": "invalid_json"}
            link = data.get("url") if isinstance(data, dict) else None
            if link:
                return {"ok": True, "url": str(link)}
            return {"ok": False, "error": "missing_url"}
        except requests.RequestException as exc:
            return {"ok": False, "error": "network", "detail": str(exc)}
        

    def get_document_versions(self, document_id: int | str):
        """Вернуть список версий документа.
        GET /api/document/versions/{id}
        """
        if not self.token:
            return []
        doc_id = self._stringify_id(document_id)
        if not doc_id:
            return []
        cache_key = f"docver:{doc_id}"
        cached = self._cached_get(cache_key)
        if cached is not None:
            return cached
        url = f"{self.base_url}/api/document/versions/{doc_id}"
        try:
            r = requests.get(url, headers=self._headers(), timeout=12)
            if r.status_code == 401:
                self.logout()
                return []
            r.raise_for_status()
            data = r.json()
            # Сервер отдаёт {"file_name": "...", "versions": [...]} - приведём к единому виду
            if isinstance(data, dict):
                data = {
                    "file_name": data.get("file_name") or data.get("fileName") or "",
                    "versions": list(data.get("versions") or []),
                }
            elif isinstance(data, list):
                data = {"file_name": "", "versions": data}
            else:
                data = {"file_name": "", "versions": []}

            if isinstance(data, dict):
                versions = data.get("versions") or data.get("items") or []
            elif isinstance(data, list):
                versions = data
            else:
                versions = []
            self.cache[cache_key] = (time.time(), versions)
            return versions
        except requests.RequestException:
            return []

    def get_folder_details(self, folder_id: int | str, force: bool = False):
        fid = self._stringify_id(folder_id)
        if not fid:
            return None
        cache_key = f"folder:{fid}"
        if not force:
            cached = self._cached_get(cache_key)
            if cached is not None: return cached
        url = f"{self.base_url}/api/folder/{fid}"
        try:
            r = requests.get(url, headers=self._headers(), timeout=12)
            if r.status_code == 401: self.logout(); return None
            r.raise_for_status()
            data = r.json()
            self.cache[cache_key] = (time.time(), data)
            return data
        except requests.RequestException:
            return None

    # CRUD
    def create_folder(self, project_id: int | str, parent_folder_id: int | str | None, name: str):
        url = f"{self.base_url}/api/folder/add"
        headers = {"Authorization": f"Bearer {self.token}", "Content-Type": "application/json", "accept": "*/*"}
        payload = {
            "projectId": project_id,
            "name": name.strip(),
            "id": 0,
            "parentFolderId": None if not parent_folder_id else self._stringify_id(parent_folder_id),
        }
        r = requests.post(url, headers=headers, json=payload, timeout=10)
        # в вашем рабочем примере считались оба успеха: 200 и 201
        if r.status_code in (200, 201):
            try:
                data = r.json()
                return data.get("id") or data.get("Id") or True  # верните id, если есть; иначе True
            except Exception:
                return True
        return False


    def delete_folder(self, folder_id: int | str) -> bool:
        folder_id_str = self._stringify_id(folder_id)
        if not folder_id_str:
            return False
        url = f"{self.base_url}/api/folder/delete/{folder_id_str}"
        try:
            r = requests.delete(url, headers=self._headers(), timeout=20)
            return r.status_code in (200, 204)
        except requests.RequestException:
            return False

    def update_folder(self, folder_id: int | str, project_id: int | str, name: str, parent_folder_id: int | str) -> bool:
        folder_id_str = self._stringify_id(folder_id)
        parent_id_str = self._stringify_id(parent_folder_id) if parent_folder_id else "0"
        url = f"{self.base_url}/api/folder/update/{folder_id_str}"
        payload = {"projectId": project_id, "name": name, "id": folder_id_str, "parentFolderId": parent_id_str}
        try:
            r = requests.put(url, headers={**self._headers(),"Content-Type":"application/json"}, json=payload, timeout=20)
            return r.status_code in (200, 204)
        except requests.RequestException:
            return False

    def delete_document(self, document_id: int | str) -> bool:
        doc_id = self._stringify_id(document_id)
        if not doc_id:
            return False
        url = f"{self.base_url}/api/document/delete/{doc_id}"
        try:
            r = requests.delete(url, headers=self._headers(), timeout=20)
            return r.status_code in (200, 204)
        except requests.RequestException:
            return False

    def rename_document(self, document_id: int | str, new_name: str) -> bool:
        doc_id = self._stringify_id(document_id)
        if not doc_id:
            return False
        url = f"{self.base_url}/api/document/update/{doc_id}"
        payload = {"id": doc_id, "fileName": new_name}
        try:
            r = requests.put(url, headers={**self._headers(),"Content-Type":"application/json"}, json=payload, timeout=20)
            return r.status_code in (200, 204)
        except requests.RequestException:
            return False

    # в APIClient
    def download_file(self, file_id: int | str, file_name: str, progress_cb=None):
        if not self.token: return None
        os.makedirs(DOWNLOAD_DIR, exist_ok=True)
        doc_id = self._stringify_id(file_id)
        if not doc_id:
            return None
        safe = _sanitize_filename(file_name or f"file_{doc_id}.bin")
        filepath = os.path.join(DOWNLOAD_DIR, safe)
        url = f"{self.base_url}/api/document/download/{doc_id}"
        try:
            with requests.get(url, headers=self._headers(), stream=True, timeout=60) as r:
                r.raise_for_status()
                total = int(r.headers.get("Content-Length") or 0)
                done = 0
                chunk = 256 * 1024
                with open(filepath, "wb") as f:
                    for part in r.iter_content(chunk_size=chunk):
                        if not part:
                            continue
                        f.write(part)
                        if progress_cb and total:
                            done += len(part)
                            progress_cb(done, total)
            return filepath
        except requests.RequestException:
            return None

    def write_file_to(self, file_id: int | str, out_fp, progress_cb=None, max_retries: int = 3) -> bool:
        """Stream file from API directly into a writable file-like object out_fp.
        Avoids saving to DOWNLOAD_DIR. Returns True on success.
        """
        if not self.token:
            return False
        doc_id = self._stringify_id(file_id)
        if not doc_id:
            return False
        url = f"{self.base_url}/api/document/download/{doc_id}"
        
        for attempt in range(max_retries):
            try:
                with requests.get(url, headers=self._headers(), stream=True, timeout=60) as r:
                    # Handle 401 Unauthorized - try to refresh token and retry once
                    if r.status_code == 401 and attempt == 0:
                        sync_log("write_file_to: got 401, trying to refresh token...")
                        if self._handle_401():
                            continue
                        else:
                            return False
                    
                    r.raise_for_status()
                    total = int(r.headers.get("Content-Length") or 0)
                    done = 0
                    chunk = 256 * 1024
                    for part in r.iter_content(chunk_size=chunk):
                        if not part:
                            continue
                        out_fp.write(part)
                        if progress_cb and total:
                            done += len(part)
                            progress_cb(done, total)
                return True
            except requests.Timeout:
                sync_log("write_file_to: timeout on attempt {}/{}", attempt + 1, max_retries)
                if attempt < max_retries - 1:
                    time.sleep(1)
                    continue
                return False
            except requests.RequestException as e:
                sync_log("write_file_to: request exception: {}", str(e))
                return False
        return False


    def upload_file(self, folder_id: int | str, local_path: str, filename: str, max_retries: int = 3):
        """Upload a single file to a specific cloud folder via multipart POST.
        Multipart fields:
          - files: binary
          - documentMetadata: JSON string like: [{"filename":"<name>","documentType":100}]
        Success: any 2xx. Response body is not required.
        After success, folder cache is invalidated. Stores last status in
        self._last_upload_status for logging by callers.
        
        Args:
            max_retries: Number of retry attempts on timeout (default 3)
        """
        if not self.token:
            return False
        folder_id_str = self._stringify_id(folder_id)
        if not folder_id_str:
            return False
        url = f"{self.base_url}/api/document/upload/{folder_id_str}"
        
        for attempt in range(max_retries):
            status = 0
            try:
                # sanitize filename
                try:
                    safe_filename = _sanitize_filename(filename)
                except Exception:
                    safe_filename = (filename or "").strip()
                meta = [{"filename": safe_filename, "documentType": 100}]
                metadata_json = json.dumps(meta, ensure_ascii=False)
                
                with open(local_path, "rb") as f:
                    files = {
                        "files": (safe_filename, f, "application/octet-stream"),
                        "documentMetadata": (None, metadata_json),
                    }
                    r = requests.post(url, headers=self._headers(), files=files, timeout=120)
                    status = int(r.status_code)
                
                # Handle 401 Unauthorized - try to refresh token and retry once
                if status == 401 and attempt == 0:
                    sync_log("upload_file: got 401, trying to refresh token...")
                    if self._handle_401():
                        continue
                    else:
                        # Token refresh failed, logout
                        return False
                
                # store last status for external logging
                try:
                    setattr(self, "_last_upload_status", status)
                except Exception:
                    pass
                    
                ok = 200 <= status < 300
                if ok:
                    try:
                        self.cache.pop(f"folder:{folder_id_str}", None)
                    except Exception:
                        pass
                return ok
                
            except requests.Timeout:
                sync_log("upload_file: timeout on attempt {}/{}", attempt + 1, max_retries)
                if attempt < max_retries - 1:
                    time.sleep(1)
                    continue
                # Final timeout - store status and return False
                try:
                    setattr(self, "_last_upload_status", 0)
                except Exception:
                    pass
                return False
                
            except requests.RequestException as e:
                sync_log("upload_file: request exception: {}", str(e))
                try:
                    setattr(self, "_last_upload_status", status or 0)
                except Exception:
                    pass
                return False
class ColumnsPopup(QWidget):
    toggled = Signal(int, bool)
    def __init__(self, table: QTableView, parent=None):
        flags = Qt.Popup | Qt.FramelessWindowHint
        super().__init__(parent, flags)
        self.setObjectName("columnsPopup")
        self.table = table
        self.setAttribute(Qt.WA_TranslucentBackground, False)
        self._cb_style = NikCheckBoxStyle(self.style())

        self.wrap = QFrame(self)
        self.wrap.setObjectName("propsCard")

        
        self.vl = QVBoxLayout(self.wrap); self.vl.setContentsMargins(8,8,8,8); self.vl.setSpacing(4)
        lay = QVBoxLayout(self); lay.setContentsMargins(0,0,0,0); lay.addWidget(self.wrap)

        self._checks = []
        self.rebuild()

    def rebuild(self):
        # очистить
        for i in reversed(range(self.vl.count())):
            w = self.vl.itemAt(i).widget()
            if w: w.deleteLater()
        self._checks.clear()

        model = self.table.model()
        if not model: return
        cols = model.columnCount()

        # Чекбоксы по столбцам (пропускаем 0-й и "Замечания")
        for col in range(1, cols):
            title = model.headerData(col, Qt.Horizontal) or f"Столбец {col}"
            if str(title).strip().lower() == "замечания":
                continue
            cb = QCheckBox(str(title), self.wrap)
            cb.setStyle(self._cb_style)
            cb.setProperty("menuitem", True)
            try:
                cb.setChecked(not self.table.isColumnHidden(col))
            except Exception:
                cb.setChecked(True)
            def _on_toggle(on, c=col):
                try:
                    self.table.setColumnHidden(c, not on)
                except Exception:
                    pass
                try:
                    mw = self.window()
                    if hasattr(mw, '_save_columns_visibility'):
                        mw._save_columns_visibility()
                except Exception:
                    pass
            cb.toggled.connect(_on_toggle)
            self.vl.addWidget(cb)
            self._checks.append(cb)

        # Кнопки «все/ничего»
        row = QWidget(self.wrap); hl = QHBoxLayout(row); hl.setContentsMargins(0,6,0,0)
        btn_all = QPushButton("Показать все", row); btn_none = QPushButton("Скрыть все", row)
        btn_all.setProperty("secondary", True); btn_none.setProperty("secondary", True)
        btn_all.clicked.connect(lambda: [cb.setChecked(True) for cb in self._checks])
        btn_none.clicked.connect(lambda: [cb.setChecked(False) for cb in self._checks])
        hl.addWidget(btn_all); hl.addWidget(btn_none)
        self.vl.addWidget(row)

    def open_for(self, anchor: QWidget):
        self.rebuild()
        pos = anchor.mapToGlobal(QPoint(0, anchor.height()))
        self.move(pos)
        self.show()

