class FilesTableModel(QAbstractTableModel):
    HEADERS = ["", "Название", "Версия", "Тип", "Формат", "Кем создан", "Создано", "Изменено", "Кем изменено"]
    SORT_ROLE = Qt.UserRole + 1


    def __init__(self, items: list, icon_provider: IconProvider, checked: set):
        super().__init__()
        self._data = items or []
        self._icon_provider = icon_provider
        self.checked = checked  # общее множество отмеченных ключей
        
    def _cb_key(self, item: dict) -> tuple:
        """Генерирует ключ для чекбокса независимо от наличия id"""
        return (item.get("type"), item.get("id") or f"tmp:{id(item)}")
        

    def rowCount(self, parent=QModelIndex()): 
        return len(self._data)

    def columnCount(self, parent=QModelIndex()): 
        return len(self.HEADERS)

    def item_at(self, row: int) -> dict:
        if 0 <= row < len(self._data): 
            return self._data[row]
        return {}

    def headerData(self, section, orientation, role=Qt.DisplayRole):
        if role == Qt.DisplayRole and orientation == Qt.Horizontal:
            try: return self.HEADERS[section]
            except IndexError: return ""
        return None

    def _sort_key(self, item: dict, col: int):
        t = (item.get("type") or "").lower()
        name = (item.get("originalName") or item.get("name") or "")
        ext = file_ext(name)
        if col == 0:
            # Больше не сортируем по чек-состоянию, чтобы строки не смещались
            return 0
        if col == 1:
            return name.lower()
        if col == 2:
            try:
                return float(item.get("version") or 0)
            except (ValueError, TypeError):
                return 0.0
        if col == 3:
            return 0 if t == "folder" else 1
        if col == 4:
            return ext
        if col == 5:
            return (item.get("createdBy") or "").lower()
        if col == 6:
            return parse_date_like(item.get("createTime") or item.get("createdAt"))
        if col == 7:
            return parse_date_like(item.get("modifTime") or item.get("updatedAt") or item.get("modifiedDate"))
        if col == 8:
            return item.get("modifiedBy") or item.get("author") or ""
        return 0


    def data(self, index, role=Qt.DisplayRole):
        if not index.isValid():
            return None
        item = self._data[index.row()]
        col = index.column()

        # ВАЖНО: отдаем весь dict строки в Qt.UserRole - для контекстного меню/служебных методов
        if role == Qt.UserRole:
            return item

        if role == Qt.DecorationRole and col == 1:
            return self._icon_provider.get_icon(item)

        if role == Qt.CheckStateRole and col == 0:
            # Используем _cb_key для всех элементов
            key = self._cb_key(item)
            current_state = Qt.Checked if key in self.checked else Qt.Unchecked
            return current_state

        if role == Qt.DisplayRole:
            if col == 0:
                return ""  # чекбокс
            if col == 1:
                return item.get("originalName") or item.get("name") or "Без имени"
            if col == 2:
                return str(item.get("version") or "")
            if col == 3:
                return "Папка" if (item.get("type") == "folder") else "Файл"
            if col == 4:
                name = item.get("originalName") or item.get("name") or ""
                return file_ext(name).upper()
            if col == 5:
                return item.get("createdBy") or ""
            if col == 6:
                val = item.get("createTime") or item.get("createdAt") or ""
                ts = parse_date_like(val)
                return _user_display_datetime(ts) if ts > 0 else val
            if col == 7:
                val = item.get("modifTime") or item.get("updatedAt") or item.get("modifiedDate") or ""
                ts = parse_date_like(val)
                return _user_display_datetime(ts) if ts > 0 else val
            if col == 8: 
                return (item.get("modifiedBy") or item.get("author") or "")
            return ""

        if role == FilesTableModel.SORT_ROLE:
            item = self._data[index.row()]
            return self._sort_key(item, index.column())

        return None

    def flags(self, index):
        if not index.isValid(): return Qt.ItemIsEnabled
        item = self._data[index.row()]; col = index.column()
        base = Qt.ItemIsEnabled | Qt.ItemIsSelectable
        if col == 0:
            # Все элементы в колонке 0 могут быть отмечены
            return base | Qt.ItemIsUserCheckable
        return base

    def setData(self, index, value, role=Qt.EditRole):
        if not index.isValid(): return False
        item = self._data[index.row()]; col = index.column()
        if role == Qt.CheckStateRole and col == 0:
            # Используем _cb_key для всех элементов
            key = self._cb_key(item)
            if value == Qt.Checked: self.checked.add(key)
            else: self.checked.discard(key)
            self.dataChanged.emit(index, index, [Qt.CheckStateRole])
            return True
        return False


class CheckBoxDelegate(QStyledItemDelegate):
    BOX = 18
    RADIUS = 3
    BORDER_W = 2
    FIXED_WIDTH = CHECKBOX_COLUMN_WIDTH  # Используем глобальную константу

    def paint(self, painter, option, index):
        # Кастомная отрисовка чекбокса только в 0-й колонке
        if index.column() != 0:
            return super().paint(painter, option, index)

        r = option.rect
        size = self.BOX  # 18px - фиксированный размер чекбокса
        # Центрируем чекбокс идеально по центру столбца
        actual_width = min(r.width(), self.FIXED_WIDTH)
        x = r.x() + (actual_width - size) // 2
        y = r.y() + (r.height() - size) // 2

        painter.save()
        try:
            painter.setRenderHint(QPainter.Antialiasing, True)

            # Draw PNG indicator icons and return early
            state = index.model().data(index, Qt.CheckStateRole)
            if state == Qt.Checked:
                _icon_path = CHECK_ICON_ON_PATH
            elif state == Qt.PartiallyChecked:
                _icon_path = CHECK_ICON_MID_PATH
            else:
                _icon_path = CHECK_ICON_OFF_PATH

            _dark = _is_dark_mode()
            try:
                if _dark:
                    _icon = load_white_icon(_icon_path)
                    _pm = _icon.pixmap(size, size)
                else:
                    _icon = QIcon(_icon_path)
                    _pm = _icon.pixmap(size, size)
            except Exception:
                _pm = QPixmap()

            if _pm.isNull() and _icon_path:
                try:
                    _base = QPixmap(_icon_path)
                    if not _base.isNull():
                        if _dark:
                            _base = _tint_pixmap(_base, QColor(Qt.white))
                        _pm = _base.scaled(size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                except Exception:
                    pass

            if not _pm.isNull():
                # Проверяем hover и selection на строке для темной и светлой темы
                row_hover = getattr(option.widget, "_hover_row", -1)
                is_row_hover = (index.row() == row_hover)
                
                # Проверяем selection через selection model для надёжности
                is_selected = bool(option.state & QStyle.State_Selected)
                if not is_selected and option.widget:
                    try:
                        sm = option.widget.selectionModel()
                        if sm and sm.isRowSelected(index.row(), QModelIndex()):
                            is_selected = True
                    except Exception:
                        pass
                
                # При hover или selection на строке красим чекбокс в черный (и в светлой, и в темной теме)
                if is_row_hover or is_selected:
                    temp_pm = QPixmap(_pm.size())
                    temp_pm.fill(Qt.transparent)
                    p = QPainter(temp_pm)
                    p.drawPixmap(0, 0, _pm)
                    p.setCompositionMode(QPainter.CompositionMode_SourceIn)
                    p.fillRect(temp_pm.rect(), QColor("#000000"))
                    p.end()
                    _pm = temp_pm
                
                _dx = x + (size - _pm.width()) // 2
                _dy = y + (size - _pm.height()) // 2
                painter.drawPixmap(int(_dx), int(_dy), _pm)
                return

            # Рамка квадрата
            rect = QRectF(x, y, size, size)
            dark = bool(getattr(option.widget, "_dark_theme", False))

            # Determine states for hover and selection inside the widget if available
            hover_idx = getattr(option.widget, "_hover_index", QModelIndex())
            pressed_idx = getattr(option.widget, "_pressed_index", QModelIndex())
            row_hover = getattr(option.widget, "_hover_row", -1)
            is_hover = hover_idx.isValid() and index == hover_idx
            is_pressed = pressed_idx.isValid() and index == pressed_idx
            is_selected = bool(option.state & QStyle.State_Selected)
            is_row_hover = (index.row() == row_hover)

            # Colors
            hover_fill = QColor("#FFE3C2")
            selected_fill = QColor("#FFCA91")
            pressed_fill = QColor("#FFCA91")
            checked_tick = QColor("#FFFFFF") if dark else QColor("#000000")
            border_col = QColor("#FFFFFF") if dark else QColor("#222")

            # Background for the checkbox square depending on state
            state = index.model().data(index, Qt.CheckStateRole)
            fill_brush = Qt.NoBrush
            if state == Qt.Checked:
                # Убираем оранжевую заливку для отмеченных чекбоксов - только рамка и галочка
                fill_brush = Qt.NoBrush
            elif is_hover and state != Qt.Checked:
                fill_brush = QBrush(hover_fill)
            else:
                fill_brush = Qt.NoBrush

            # Harmonize with row state: override fill and line colors
            if is_pressed:
                fill_brush = QBrush(pressed_fill)
            elif is_selected:
                fill_brush = QBrush(selected_fill)
            elif is_row_hover or is_hover:
                fill_brush = QBrush(hover_fill)
            if dark and (is_row_hover or is_hover or is_selected or is_pressed):
                border_col = QColor("#222222")
            # Draw rounded rect (fill + border)
            painter.setPen(QPen(border_col, max(1, int(self.BORDER_W))))
            if isinstance(fill_brush, QBrush) and not fill_brush.style() == Qt.NoBrush:
                painter.setBrush(fill_brush)
            else:
                painter.setBrush(Qt.NoBrush)
            painter.drawRoundedRect(rect, self.RADIUS, self.RADIUS)

            # Draw checkmark if checked
            if state == Qt.Checked:
                if dark and (is_row_hover or is_hover or is_selected or is_pressed):
                    checked_tick = QColor("#222222")
                path = QPainterPath()
                path.moveTo(rect.left() + 0.22 * size, rect.top() + 0.55 * size)
                path.lineTo(rect.left() + 0.44 * size, rect.top() + 0.75 * size)
                path.lineTo(rect.left() + 0.80 * size, rect.top() + 0.30 * size)
                painter.setPen(QPen(checked_tick, max(2, int(size * 0.12)), Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
                painter.setBrush(Qt.NoBrush)
                painter.drawPath(path)
        finally:
            painter.restore()

    def sizeHint(self, option, index):
        """Возвращаем фиксированный размер для первого столбца чтобы предотвратить его расширение"""
        if index.column() == 0:
            return QSize(self.FIXED_WIDTH, 28)  # Фиксированная ширина, высота 28px
        return super().sizeHint(option, index)

    def editorEvent(self, event, model, option, index):
        # Обрабатываем события для чекбокса в первой колонке
        if index.column() == 0 and index.flags() & Qt.ItemIsUserCheckable:
            et = event.type()
            if et == QEvent.MouseButtonPress or et == QEvent.MouseButtonRelease:
                mouse_btn = getattr(event, "button", lambda: Qt.NoButton)()
                if mouse_btn == Qt.LeftButton:
                    # Проверяем попадание в область чекбокса
                    rect = option.rect
                    size = self.BOX
                    actual_width = min(rect.width(), self.FIXED_WIDTH)
                    x = rect.x() + (actual_width - size) // 2
                    y = rect.y() + (rect.height() - size) // 2
                    checkbox_rect = QRect(x, y, size, size)
                    
                    cursor_pos = event.position().toPoint() if hasattr(event, "position") else event.pos()
                    
                    if checkbox_rect.contains(cursor_pos):
                        if et == QEvent.MouseButtonRelease:
                            # Переключаем состояние
                            state = model.data(index, Qt.CheckStateRole)
                            new_state = Qt.Unchecked if state == Qt.Checked else Qt.Checked
                            
                            # Применяем ко всем выбранным строкам
                            widget = option.widget
                            selected_rows = set()
                            if widget:
                                sm = widget.selectionModel()
                                if sm:
                                    selected_indexes = sm.selectedIndexes()
                                    for idx in selected_indexes:
                                        if idx.column() == 0:
                                            selected_rows.add(idx.row())
                            
                            # Всегда включаем текущую строку
                            selected_rows.add(index.row())
                            
                            print(f"[CheckBoxDelegate] Selected rows: {sorted(selected_rows)}")
                            
                            for row in selected_rows:
                                idx0 = model.index(row, 0)
                                model.setData(idx0, new_state, Qt.CheckStateRole)
                            return True
                        return True
        return False

        if et == QEvent.KeyPress and getattr(event, "key", lambda: None)() in (Qt.Key_Space, Qt.Key_Return, Qt.Key_Enter):
            state = model.data(index, Qt.CheckStateRole)
            new = Qt.Unchecked if state == Qt.Checked else Qt.Checked
            try:
                model.setData(index, new, Qt.CheckStateRole)
            except Exception:
                pass
            try:
                view = option.widget
                sm = view.selectionModel() if hasattr(view, "selectionModel") else None
                if sm is not None:
                    for r in sm.selectedRows():
                        if r.row() == index.row():
                            continue
                        idx0 = model.index(r.row(), 0)
                        try:
                            model.setData(idx0, new, Qt.CheckStateRole)
                        except Exception:
                            pass
            except Exception:
                pass
            return True

        return True

class StickyMenu(QMenu):
    def mouseReleaseEvent(self, e):
        p = e.position().toPoint() if hasattr(e, "position") else e.pos()
        act = self.actionAt(p)
        if act is not None and act.isCheckable() and act.isEnabled():
            act.toggle()
            e.accept()
            return
        super().mouseReleaseEvent(e)

class HeaderCheckButton(QAbstractButton):
    BOX = 18
    RADIUS = 4
    BORDER_W = 2
    stateChanged = Signal(int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setCheckable(True)
        self._partial = False
        self._setting_checked = False  # Флаг для предотвращения рекурсии
        self.setCursor(Qt.PointingHandCursor)
        self.setFocusPolicy(Qt.NoFocus)
        self.setMouseTracking(True)  # Enable mouse tracking for hover detection
        # Фиксируем размер чтобы избежать сдвигов при изменении состояния
        self.setFixedSize(self.BOX, self.BOX)
        # Блокируем изменение размера политикой
        self.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
        # Подключаем обработку переключения состояния
        self.toggled.connect(self._on_toggled)

    def sizeHint(self):
        return QSize(self.BOX, self.BOX)
    
    def minimumSizeHint(self):
        return QSize(self.BOX, self.BOX)
    
    def _on_toggled(self, checked):
        """Обработка переключения - сброс partial и эмиссия stateChanged"""
        # Игнорируем если это программный вызов из setChecked
        if self._setting_checked:
            return
        
        # При любом переключении сбрасываем partial состояние
        if self._partial:
            self._partial = False
        # Эмитируем stateChanged с новым состоянием
        state_int = self._checkStateAsInt()
        self.stateChanged.emit(state_int)

    def setPartial(self, v: bool):
        old_partial = self._partial
        self._partial = bool(v)
        # эмитим смену состояния только если состояние действительно изменилось
        if old_partial != self._partial:
            self.stateChanged.emit(self._checkStateAsInt())

    def isPartial(self) -> bool:
        return self._partial

    # Совместимость с QCheckBox API
    def setCheckState(self, st: int):
        if st == Qt.Checked:
            self.setChecked(True)
            self._partial = False
        elif st == Qt.Unchecked:
            self.setChecked(False)
            self._partial = False
        else:
            # частичная
            self.setChecked(False)
            self._partial = True
        self.stateChanged.emit(self._checkStateAsInt())
        self.repaint()

    def checkState(self) -> int:
        if self.isChecked():
            return Qt.Checked
        return Qt.PartiallyChecked if self._partial else Qt.Unchecked
    
    def _checkStateAsInt(self) -> int:
        """Возвращает состояние чекбокса как целое число"""
        state = self.checkState()
        # Преобразуем Qt.CheckState в int
        if hasattr(state, 'value'):
            return int(state.value)
        return int(state)

    def setChecked(self, on: bool):
        prev = self.isChecked()
        # Устанавливаем флаг чтобы _on_toggled знал что это программный вызов
        self._setting_checked = True
        try:
            super().setChecked(on)
        finally:
            self._setting_checked = False
        
        if prev != on:
            # Сбрасываем partial при любом изменении checked состояния
            if self._partial:
                self._partial = False
            # Эмитируем stateChanged вручную только для программных вызовов
            self.stateChanged.emit(self._checkStateAsInt())

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, True)
        size = min(self.BOX, min(self.width(), self.height()))
        x = (self.width() - size) // 2
        y = (self.height() - size) // 2

        # Determine which icon to show based on state
        dark = _is_dark_mode()
        is_hovered = self.underMouse()
        
        if self.isChecked():
            _icon_path = CHECK_ICON_ON_PATH
        elif getattr(self, "_partial", False):
            _icon_path = CHECK_ICON_MID_PATH
        else:
            _icon_path = CHECK_ICON_OFF_PATH

        # Load and draw the icon
        try:
            if dark:
                _icon = load_white_icon(_icon_path)
                _pm = _icon.pixmap(size, size)
            else:
                _icon = QIcon(_icon_path)
                _pm = _icon.pixmap(size, size)
        except Exception:
            _pm = QPixmap()

        # Fallback to manual loading if QIcon fails
        if _pm.isNull() and _icon_path:
            try:
                _base = QPixmap(_icon_path)
                if not _base.isNull():
                    if dark:
                        _base = _tint_pixmap(_base, QColor(Qt.white))
                    _pm = _base.scaled(size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
            except Exception:
                pass

        # Tint to black on hover in dark theme
        if dark and is_hovered and not _pm.isNull():
            try:
                _pm = _tint_pixmap(_pm, QColor(Qt.black))
            except Exception:
                pass

        # Draw the icon if we have one
        if not _pm.isNull():
            px = int(x + (size - _pm.width()) // 2)
            py = int(y + (size - _pm.height()) // 2)
            p.drawPixmap(px, py, _pm)
            p.end()
            return

        # Fallback to drawn checkbox if no icons available
        rect = QRectF(x, y, size, size)
        hovered = self.underMouse()
        pressed = self.isDown()
        
        if dark:
            fill_color = QColor("#101010")
            if hovered:
                fill_color = QColor("#181818")
            if pressed:
                fill_color = QColor("#060606")
            border_color = QColor("#fefefe")
            mark_color = QColor("#fefefe")
        else:
            fill_color = QColor("#ffffff")
            if pressed:
                fill_color.setAlpha(230)
            elif hovered:
                fill_color.setAlpha(210)
            border_color = QColor("#010101")
            mark_color = QColor("#010101")

        p.setPen(QPen(border_color, self.BORDER_W))
        p.setBrush(fill_color)
        p.drawRoundedRect(rect, self.RADIUS, self.RADIUS)

        if self.isChecked():
            path = QPainterPath()
            path.moveTo(rect.left() + 0.22*size, rect.top() + 0.55*size)
            path.lineTo(rect.left() + 0.44*size, rect.top() + 0.75*size)
            path.lineTo(rect.left() + 0.80*size, rect.top() + 0.30*size)
            p.setPen(QPen(mark_color, max(2, int(size * 0.12)),
                          Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            p.drawPath(path)
        elif self._partial:
            p.setPen(QPen(mark_color, max(2, int(size * 0.12))))
            ymid = rect.center().y()
            p.drawLine(rect.left() + 0.25*size, ymid, rect.right() - 0.25*size, ymid)

class BusyDots(QWidget):
    def __init__(self, parent=None, color="#F7921E", dots=5, r_min=2, r_max=4, spacing=6, interval_ms=80):
        super().__init__(parent)
        self.color = QColor(color)
        self.dots = int(dots)
        self.r_min, self.r_max = float(r_min), float(r_max)
        self.spacing = int(spacing)
        self._t = 0.0
        self._min = 0
        self._max = 0
        self._val = 0
        self._indeterminate = True

        self._timer = QTimer(self)
        self._timer.setInterval(int(interval_ms))
        self._timer.timeout.connect(self._tick)

        step = int(2*self.r_max + self.spacing)
        w = self.dots * step - self.spacing
        h = int(2*self.r_max + 4)
        self.setFixedSize(w, h)

    # --- совместимость с QProgressBar API ---
    def setRange(self, mn: int, mx: int):
        self._min, self._max = int(mn), int(mx)
        self._indeterminate = (mn == 0 and mx == 0)
        if self.isVisible():
            self._timer.start()
        else:
            self._timer.stop()
        self.update()

    def setValue(self, v: int):
        self._val = int(v)
        self.update()

    def setVisible(self, on: bool):
        super().setVisible(on)
        if on:
            self._timer.start()
        else:
            self._timer.stop()

    def sizeHint(self):
        return QSize(self.width(), self.height())

    # --- рисование ---
    def _tick(self):
        self._t = (self._t + 0.12) % 1000.0
        self.update()

    def paintEvent(self, _e):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, True)
        cy = self.height() / 2.0
        step = 2*self.r_max + self.spacing

        if self._indeterminate:
            # бегущая волна: точки «дышат»
            for i in range(self.dots):
                phase = (self._t - i*0.25) * 2.0 * math.pi
                s = (math.sin(phase) + 1.0) * 0.5  # 0..1
                r = self.r_min + s * (self.r_max - self.r_min)
                c = QColor(self.color); c.setAlpha(80 + int(s * 175))
                p.setBrush(c); p.setPen(Qt.NoPen)
                cx = i * step + self.r_max
                p.drawEllipse(QRectF(cx - r, cy - r, 2*r, 2*r))
        else:
            # детермин.— заполняем точки слева направо по value
            total = max(1, self._max - self._min)
            frac = max(0.0, min(1.0, (self._val - self._min) / total))
            target = frac * self.dots
            for i in range(self.dots):
                s = max(0.0, min(1.0, target - i))  # 0..1 сколько «заряжена» точка
                # лёгкая пульсация активной точки
                if 0.0 < s < 1.0:
                    s = max(0.0, min(1.0, s + 0.15*math.sin(self._t*2*math.pi)))
                r = self.r_min + s * (self.r_max - self.r_min)
                c = QColor(self.color); c.setAlpha(60 + int(s * 195))
                p.setBrush(c); p.setPen(Qt.NoPen)
                cx = i * step + self.r_max
                p.drawEllipse(QRectF(cx - r, cy - r, 2*r, 2*r))
        p.end()

class WaitDialog(QDialog):
    def __init__(self, text: str, parent=None):
        super().__init__(parent)
        self.setModal(True)
        try:
            self.setWindowTitle("Подождите")
        except Exception:
            # Fallback in case of encoding issues
            self.setWindowTitle(str("Подождите"))
        self.setWindowTitle("Подождите")
        self.setWindowFlags(Qt.Dialog | Qt.WindowTitleHint | Qt.CustomizeWindowHint)
        try:
            self.setWindowTitle("Подождите")
        except Exception:
            pass
        try:
            if ICON_PATH and os.path.exists(ICON_PATH):
                self.setWindowIcon(QIcon(ICON_PATH))
        except Exception:
            pass
        
        app = QApplication.instance()
        if app:
            current_theme = getattr(app, "nik_theme", THEME_LIGHT)
            is_dark = current_theme == THEME_DARK
            _set_window_theme_dark(self, dark=is_dark)

        # Main row: text + spinner only
        row = QHBoxLayout(); row.setContentsMargins(12,10,12,12); row.setSpacing(8)
        self._lbl = QLabel(text, self)
        self._lbl.setAlignment(Qt.AlignVCenter | Qt.AlignLeft)
        spinner = BusyDots(self)
        spinner.setRange(0, 0)
        spinner.setVisible(True)
        self._spinner = spinner
        row.addWidget(self._lbl, 1)
        row.addWidget(spinner, 0, Qt.AlignRight | Qt.AlignVCenter)

        lay = QVBoxLayout(self)
        lay.addLayout(row)
        self.setLayout(lay)
        self.resize(400, 80)
        QTimer.singleShot(0, lambda: QApplication.processEvents())

    def set_message(self, text: str):
        self._lbl.setText(text)
        self._adjust_width_to_content()
        QApplication.processEvents()

    def _adjust_width_to_content(self) -> None:
        """Adjust dialog width to fit the message text."""
        try:
            fm = self._lbl.fontMetrics()
            text = self._lbl.text()
            text_width = fm.horizontalAdvance(text)
            spinner_width = 50
            margins = 12 * 2
            spacing = 8
            required_width = text_width + spinner_width + margins + spacing + 40
            current_width = self.width()
            if required_width > current_width:
                new_width = min(required_width, 800)
                self.resize(new_width, self.height())
        except Exception:
            pass

    def set_done(self, text: str, auto_close_ms: int = 1800):
        self._spinner.setVisible(False)
        self._lbl.setText(text)
        self._adjust_width_to_content()
        try:
            QTimer.singleShot(max(200, int(auto_close_ms)), self.accept)
        except Exception:
            pass


class NikCheckBoxStyle(QProxyStyle):
    """Proxy style that draws menu-like checkbox indicators."""


    def drawPrimitive(self, element, option, painter, widget=None):
        if element == QStyle.PE_IndicatorBranch:
            if not (option.state & QStyle.State_Children):
                return super().drawPrimitive(element, option, painter, widget)

            dark_attr = None
            try:
                dark_attr = getattr(widget, "_dark_theme") if widget is not None else None
            except Exception:
                dark_attr = None
            dark = bool(dark_attr) if dark_attr is not None else _is_dark_mode()

            color = QColor("#fefefe") if dark else QColor("#010101")
            if option.state & (QStyle.State_MouseOver | QStyle.State_Selected):
                color = QColor("#F7921E")

            rect = option.rect.adjusted(1, 1, -1, -1)
            icon_sz = int(max(8, min(rect.width(), rect.height(), 10)))
            direction = "down" if (option.state & QStyle.State_Open) else "right"
            pm = _branch_arrow_icon(direction, color, icon_sz)
            if not pm.isNull():
                painter.save()
                painter.setRenderHint(QPainter.Antialiasing, True)
                x = rect.x() + (rect.width() - pm.width()) / 2
                y = rect.y() + (rect.height() - pm.height()) / 2
                painter.drawPixmap(int(x), int(y), pm)
                painter.restore()
                return
        return super().drawPrimitive(element, option, painter, widget)


class ConflictListItem(QWidget):
    def __init__(self, file_icon: QIcon, name: str, status_icons: dict[str, QIcon], parent: QWidget | None = None):
        super().__init__(parent)
        self._status_icons = status_icons

        layout = QHBoxLayout(self)
        layout.setContentsMargins(8, 6, 8, 6)
        layout.setSpacing(8)

        self.icon_label = QLabel(self)
        self.icon_label.setFixedSize(24, 24)
        self.icon_label.setAlignment(Qt.AlignCenter)
        self.set_icon(file_icon)

        self.name_label = QLabel(name, self)
        self.name_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        self.name_label.setWordWrap(True)

        layout.addWidget(self.icon_label, 0, Qt.AlignTop)
        layout.addWidget(self.name_label, 1, Qt.AlignTop)

        self.status_label = QLabel(self)
        self.status_label.setFixedSize(16, 16)
        self.status_label.setAlignment(Qt.AlignCenter)
        self.status_label.setScaledContents(True)
        layout.addWidget(self.status_label, 0, Qt.AlignTop)

    def set_icon(self, icon: QIcon | None):
        if isinstance(icon, QIcon) and not icon.isNull():
            self.icon_label.setPixmap(icon.pixmap(20, 20))
        else:
            self.icon_label.clear()

    def set_status(self, status: str, tooltip: str = "") -> None:
        icon = self._status_icons.get(status)
        if icon is None or icon.isNull():
            self.status_label.clear()
        else:
            self.status_label.setPixmap(icon.pixmap(14, 14))
        self.status_label.setToolTip(tooltip or "")

    def set_name(self, name: str) -> None:
        self.name_label.setText(name)

    def set_active(self, active: bool) -> None:
        font = self.name_label.font()
        font.setBold(active)
        self.name_label.setFont(font)


class BatchDownloadDialog(QDialog):
    STATUS_ICON_FILES = {
        "ok": "ok.png",
        "process": "process.png",
        "none": "none.png",
    }

    def __init__(self, parent: QWidget | None, total: int, icon_provider: IconProvider | None):
        super().__init__(parent)
        self.setModal(True)
        self.setWindowTitle("Скачивание файлов")
        self.setWindowFlag(Qt.WindowContextHelpButtonHint, False)
        self.setWindowFlag(Qt.WindowMinimizeButtonHint, False)
        self.setMaximumSize(550, 380)
        self.resize(400, 220)

        self._allow_close = False
        self._cancelled = False
        self._decision_loop: QEventLoop | None = None
        self._decision: str = "cancel"
        self._icon_provider = icon_provider
        self._conflicts_total = 0
        self._conflict_index = 0
        self._rows: dict[str, tuple[QListWidgetItem, ConflictListItem]] = {}
        self._apply_all_style = NikCheckBoxStyle(self.style())

        self._status_icons: dict[str, QIcon] = {}
        for key, filename in self.STATUS_ICON_FILES.items():
            try:
                path = rsrc_path("icon", filename)
                if key == "process" and _is_dark_mode():
                    self._status_icons[key] = load_white_icon(path)
                else:
                    self._status_icons[key] = QIcon(path)
            except Exception:
                self._status_icons[key] = QIcon()

        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 10, 12, 8)
        layout.setSpacing(6)
        # Enforce checkbox indicators inside this dialog
        try:
            dark = _is_dark_mode()
            off_p = CHECK_ICON_OFF_PATH
            on_p  = CHECK_ICON_ON_PATH
            mid_p = CHECK_ICON_MID_PATH
            if dark:
                try:
                    off_p = _get_white_icon_path_for_dark_theme(off_p)
                    on_p  = _get_white_icon_path_for_dark_theme(on_p)
                    mid_p = _get_white_icon_path_for_dark_theme(mid_p)
                except Exception:
                    pass
            _chk_qss = (
                "QCheckBox::indicator { width: 18px; height: 18px; }\n"
                f"QCheckBox::indicator:unchecked {{ image: url('{off_p}'); }}\n"
                f"QCheckBox::indicator:checked   {{ image: url('{on_p}'); }}\n"
                f"QCheckBox::indicator:indeterminate {{ image: url('{mid_p}'); }}\n"
            )
            self.setStyleSheet((self.styleSheet() or "") + "\n" + _chk_qss)
        except Exception:
            pass

        self.info_label = QLabel("Выберите действие для файлов с совпадающими именами.", self)
        self.info_label.setWordWrap(True)
        layout.addWidget(self.info_label)

        self.conflict_label = QLabel("", self)
        self.conflict_label.setWordWrap(True)
        self.conflict_label.setMaximumHeight(80)
        self.conflict_label.setStyleSheet("QLabel { text-overflow: ellipsis; }")
        layout.addWidget(self.conflict_label)

        self.apply_all_box = QCheckBox("Применить ко всем конфликтам", self)
        self.apply_all_box.setObjectName("bulkApplyAllBox")
        self.apply_all_box.setStyle(self._apply_all_style)
        self.apply_all_box.setCursor(Qt.PointingHandCursor)
        layout.addWidget(self.apply_all_box, 0, Qt.AlignLeft)

        self.list_widget = QListWidget(self)
        self.list_widget.setSelectionMode(QAbstractItemView.NoSelection)
        self.list_widget.setFocusPolicy(Qt.NoFocus)
        self.list_widget.setUniformItemSizes(True)
        self.list_widget.setAlternatingRowColors(True)
        self.list_widget.setVerticalScrollMode(QAbstractItemView.ScrollPerPixel)
        self.list_widget.setMaximumHeight(200)
        self.list_widget.setStyleSheet("QListWidget { border: none; }")
        layout.addWidget(self.list_widget, 1)

        progress_row = QHBoxLayout()
        progress_row.setContentsMargins(0, 0, 0, 0)
        progress_row.setSpacing(8)
        self.progress_anim = BusyDots(self, color="#F7921E", dots=5, r_min=2, r_max=4, spacing=6, interval_ms=90)
        self.progress_anim.setRange(0, 0)
        self.progress_anim.setVisible(False)
        progress_row.addWidget(self.progress_anim, 0, Qt.AlignLeft | Qt.AlignVCenter)
        self.progress_label = QLabel("", self)
        progress_row.addWidget(self.progress_label, 1, Qt.AlignLeft | Qt.AlignVCenter)
        layout.addLayout(progress_row)

        btn_row = QHBoxLayout()
        btn_row.setSpacing(8)
        btn_row.addStretch(1)
        layout.addLayout(btn_row)

        self.btn_replace = QPushButton("Заменить", self)
        self.btn_copy = QPushButton("Создать копию", self)
        self.btn_cancel = QPushButton("Отмена", self)
        self.btn_ok = QPushButton("Ок", self)
        self.btn_ok.setVisible(False)

        for btn in (self.btn_replace, self.btn_copy, self.btn_cancel, self.btn_ok):
            btn.setProperty("chip", True)
            btn.setProperty("chipSmall", True)
            btn.setStyleSheet("padding: 3px 10px; min-height: 24px; font-size: 11px;")
            btn_row.addWidget(btn)

        self.btn_replace.clicked.connect(lambda: self._emit_decision("replace"))
        self.btn_copy.clicked.connect(lambda: self._emit_decision("copy"))
        self.btn_cancel.clicked.connect(self._cancel)
        self.btn_ok.clicked.connect(self.accept)

    # --- API ---
    def add_entry(self, key: str, item_info: dict, display_name: str) -> None:
        qicon = QIcon()
        try:
            if self._icon_provider is not None:
                qicon = self._icon_provider.get_icon(item_info)
        except Exception:
            qicon = QIcon()
        row = ConflictListItem(qicon, display_name, self._status_icons, self)
        item = QListWidgetItem(self.list_widget)
        item.setSizeHint(QSize(0, 50))
        self.list_widget.setItemWidget(item, row)
        self._rows[key] = (item, row)

    def set_status(self, key: str, status: str, tooltip: str = "") -> None:
        row = self._rows.get(key)
        if not row:
            return
        if status not in self._status_icons:
            status = "none"
        row[1].set_status(status, tooltip)

    def _adjust_width_to_content(self) -> None:
        """Adjust dialog width to fit the longest file name text."""
        try:
            max_text_width = 0
            for key, (item, row) in self._rows.items():
                fm = row.name_label.fontMetrics()
                text_width = fm.horizontalAdvance(row.name_label.text())
                max_text_width = max(max_text_width, text_width)
            if max_text_width > 0:
                icon_width = 24
                status_width = 16
                margins = 12 * 2
                spacing = 8 * 2
                required_width = icon_width + max_text_width + status_width + margins + spacing + 40
                current_width = self.width()
                if required_width > current_width:
                    new_width = min(required_width, 800)
                    self.resize(new_width, self.height())
        except Exception:
            pass

    def set_name(self, key: str, name: str) -> None:
        row = self._rows.get(key)
        if row:
            row[1].set_name(name)
            self._adjust_width_to_content()

    def set_active(self, key: str, active: bool) -> None:
        for k, (_, widget) in self._rows.items():
            widget.set_active(active and k == key)

    def set_total_conflicts(self, total: int) -> None:
        self._conflicts_total = max(0, total)
        has_conflicts = self._conflicts_total > 0
        self.apply_all_box.setVisible(has_conflicts)
        self.info_label.setVisible(has_conflicts)
        try:
            self.btn_replace.setVisible(has_conflicts)
            self.btn_copy.setVisible(has_conflicts)
        except Exception:
            pass
        self.progress_anim.setVisible(False)
        self.progress_label.clear()
        if has_conflicts:
            self.conflict_label.setText("Обнаружены файлы с совпадающими именами.")
        else:
            self.conflict_label.clear()

    def update_progress(self, current: int, total: int) -> None:
        total = max(1, total)
        current = max(0, min(current, total))
        self.progress_anim.setVisible(current < total)
        self.progress_label.setText(f"Загружено: {current} из {total}")
        QApplication.processEvents()

    def ask_conflict(self, key: str, name: str, remaining: int) -> tuple[str, bool]:
        self._conflict_index = self._conflicts_total - remaining + 1 if self._conflicts_total else 1
        self.set_active(key, True)
        if remaining > 0 and not self.apply_all_box.isChecked():
            self.conflict_label.setText(f"Файл уже существует ({self._conflict_index}/{self._conflicts_total}): {name}")
        else:
            self.conflict_label.setText(f"Файл уже существует: {name}")
        self._adjust_width_to_content()
        self._decision = "cancel"
        loop = QEventLoop(self)
        self._decision_loop = loop
        loop.exec()
        self._decision_loop = None
        chosen = self._decision
        apply_all = self.apply_all_box.isChecked()
        self.set_active(key, False)
        return chosen, apply_all

    def finish(self, text: str) -> None:
        self.conflict_label.clear()
        self.apply_all_box.hide()
        self.btn_replace.hide()
        self.btn_copy.hide()
        self.btn_cancel.hide()
        self.btn_ok.show()
        self.progress_anim.setVisible(False)
        if text:
            self.progress_label.setText(text)
        self._allow_close = True
        self.set_active("", False)
        self._adjust_width_to_content()

    def was_cancelled(self) -> bool:
        return self._cancelled

    # --- internal helpers ---
    def _emit_decision(self, decision: str) -> None:
        if self._decision_loop is None:
            return
        self._decision = decision
        loop = self._decision_loop
        self._decision_loop = None
        loop.quit()

    def _cancel(self) -> None:
        self._cancelled = True
        self._emit_decision("cancel")
        self._allow_close = True
        self.reject()

    def closeEvent(self, event):
        if not self._allow_close and not self._cancelled:
            self._cancel()
        super().closeEvent(event)


class SingleDownloadDialog(QDialog):
    """Окно для одиночного скачивания с нижней строкой статуса (точки + текст)."""
    def __init__(self, parent: QWidget | None, icon_provider: IconProvider | None, item: dict, display_name: str):
        super().__init__(parent)
        self.setModal(True)
        self.setWindowTitle("Скачивание файла")
        self.setWindowFlag(Qt.WindowContextHelpButtonHint, False)
        self.setWindowFlag(Qt.WindowMinimizeButtonHint, False)
        self.resize(400, 100)

        self._cancelled = False
        self._status_icons: dict[str, QIcon] = {}
        try:
            for key, filename in BatchDownloadDialog.STATUS_ICON_FILES.items():
                path = rsrc_path("icon", filename)
                if key == "process" and _is_dark_mode():
                    self._status_icons[key] = load_white_icon(path)
                else:
                    self._status_icons[key] = QIcon(path)
        except Exception:
            pass

        layout = QVBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(6)

        # Список из одного элемента: иконка файла, имя, статус
        self.list_widget = QListWidget(self)
        self.list_widget.setSelectionMode(QAbstractItemView.NoSelection)
        self.list_widget.setFocusPolicy(Qt.NoFocus)
        layout.addWidget(self.list_widget, 1)

        qicon = QIcon()
        try:
            if icon_provider is not None:
                qicon = icon_provider.get_icon(item)
        except Exception:
            qicon = QIcon()
        self._row_widget = ConflictListItem(qicon, display_name, self._status_icons, self)
        self._row_item = QListWidgetItem(self.list_widget)
        self._row_item.setSizeHint(QSize(0, 50))
        self.list_widget.setItemWidget(self._row_item, self._row_widget)

        # Нижняя строка: точки + подпись
        progress_row = QHBoxLayout()
        progress_row.setContentsMargins(0, 0, 0, 0)
        progress_row.setSpacing(8)
        self.progress_anim = BusyDots(self, color="#F7921E", dots=5, r_min=2, r_max=4, spacing=6, interval_ms=90)
        self.progress_anim.setRange(0, 0)
        self.progress_anim.setVisible(True)
        progress_row.addWidget(self.progress_anim, 0, Qt.AlignLeft | Qt.AlignVCenter)
        self.progress_label = QLabel("Скачивание...", self)
        progress_row.addWidget(self.progress_label, 1, Qt.AlignLeft | Qt.AlignVCenter)
        layout.addLayout(progress_row)

        # Кнопки
        btn_row = QHBoxLayout()
        btn_row.setSpacing(8)
        btn_row.addStretch(1)
        layout.addLayout(btn_row)
        self.btn_cancel = QPushButton("Отмена", self)
        self.btn_ok = QPushButton("ОК", self)
        self.btn_ok.setVisible(False)
        self.btn_cancel.setProperty("chip", True)
        self.btn_cancel.setProperty("chipSmall", True)
        self.btn_cancel.setStyleSheet("padding: 3px 10px; min-height: 24px; font-size: 11px;")
        btn_row.addWidget(self.btn_cancel)
        self.btn_ok.setProperty("chip", True)
        self.btn_ok.setProperty("chipTiny", True)
        btn_row.addWidget(self.btn_ok)
        self.btn_cancel.clicked.connect(self._on_cancel)
        self.btn_ok.clicked.connect(self.accept)

    def set_status(self, status: str, tooltip: str = "") -> None:
        if status not in self._status_icons:
            status = "none"
        self._row_widget.set_status(status, tooltip)
        self._adjust_width_to_content()

    def _adjust_width_to_content(self) -> None:
        """Adjust dialog width to fit the file name text."""
        try:
            name_label = self._row_widget.name_label
            fm = name_label.fontMetrics()
            text = name_label.text()
            text_width = fm.horizontalAdvance(text)
            icon_width = 24
            status_width = 16
            margins = 8 * 2
            spacing = 8 * 2
            required_width = icon_width + text_width + status_width + margins + spacing + 40
            current_width = self.width()
            if required_width > current_width:
                new_width = min(required_width, 800)
                self.resize(new_width, self.height())
        except Exception:
            pass

    def set_name(self, name: str) -> None:
        self._row_widget.set_name(name)
        self._adjust_width_to_content()

    def update_count(self, current: int, total: int) -> None:
        total = max(1, total)
        current = max(0, min(current, total))
        # Держим точки видимыми только пока не достигли total
        self.progress_anim.setVisible(current < total)
        self.progress_label.setText(f"Скачано: {current} из {total}")
        QApplication.processEvents()

    def finish(self, ok: bool, text: str = "") -> None:
        self.progress_anim.setVisible(False)
        if ok:
            self.set_status("ok", "Файл скачан")
            if text:
                self.progress_label.setText(text)
        else:
            self.set_status("none", "Ошибка скачивания")
            if text:
                self.progress_label.setText(text)
        self.btn_cancel.hide()
        self.btn_ok.show()
        self._adjust_width_to_content()

    def was_cancelled(self) -> bool:
        return self._cancelled

    def _on_cancel(self):
        self._cancelled = True
        self.reject()

