# Sync: right-click folder -> "Синхронизировать", persistent mapping + timer
# Adds a lightweight sync manager and integrates it into MainWindow.
# SYNC_ROLE for the sync badge on the RIGHT of the text, without overlaying the folder icon.
SYNC_ROLE = QtCore.Qt.UserRole + 1111

def nik_icon(_name: str) -> QtGui.QIcon:  # type: ignore
    """Load themed icon for the sync badge (white in dark theme)."""
    p = rsrc_path("icon", "sync.png")
    if not os.path.exists(p):
        return QtGui.QIcon()
    try:
        if _is_dark_mode():
            return load_white_icon(p)
    except Exception:
        pass
